quests[13078] = { id = 13078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dahlia's Tears", description = "In this dark time, I'll not be the one to abandon a champion of the Light.\n\nWe will need something sacred for this to have a hope of saving your Bridenbrad... a remnant of a devout being that fell victim to this very same plague.\n\nGo now to the sacred soil of the passages outside my Ruby Dragonshrine where the battle is joined. As my Ruby Keepers fly down and set flame to the ground beneath undead feet, you will witness new life grow forth. Among that life are Dahlia's Tears - bring them to me.", sourceObjective = "Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia's Tears from soil freshly cleansed by a Ruby Keeper's flames.", progress = "Ah, dear Dahlia. I do miss you so.", completion = "With Dahlia's Tears and ancient magic, I fashion you some small amount of hope for your great crusader.", sourceObjectiveStatus = "unverified-source-field" }
quests[13079] = { id = 13079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of Alexstrasza", description = "You must understand, young {race}, that cleansing the body in favor of life anew is something well within my grasp... removing the plague of undeath without affecting the body, however, is beyond the scope of the powers that I control.\n\nIf this Bridenbrad is the beacon of light that you profess him to be, perhaps he will endure such a cleansing and thrive, but I cannot state with confidence that this is the salvation that you seek. Take it and go with all of my blessings.", sourceObjective = "Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown.", progress = "You have returned yet again, {class}. Why do you risk yourself so?", completion = "The breath of Alexstrasza... you have gone to the dragon-queen herself? I'm extremely grateful.\n\nI understand the risks of such cleansing and I am prepared. Proceed, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13080] = { id = 13080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hope Yet Remains", description = "<Bridenbrad raises a hand to you as he catches his breath.>\n\nIt was nearly as painful as it looked, but it was as if I could feel some of the corruption being burnt away from within my body. It seems the plague is not so readily bested though.\n\n{class}, thank you for everything that you have done. Your selfless actions have renewed my hope that there is yet great good left within this world - I can depart without fear that darkness will prevail in my absence.\n\nGo now, go with no regrets.", sourceObjective = "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of the effects of the Breath of Alexstrasza.", completion = "The Scourge plague is no simple foe to defeat. Alexstrasza's words suggest that perhaps we can yet save our Bridenbrad from the unimaginable fate of the unliving should he fall, but I will not give him up so easily.\n\nThere is yet one more path of light I would like to pursue. One more being who might avert this horrible fate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13081] = { id = 13081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Naaru", description = "I appreciate everything that you have done for us, {name}. I have one last errand for you... one last gleaming hope for a paladin who deserves any salvation that we can extend.\n\nGo now to Shattrath and speak to the naaru, A'dal. He has long been a beacon of light and powerful ally to devout paladins. Impart Bridenbrad's story and seek any aid that he might have to offer.\n\nI cannot impress how important it is that you move quickly - I fear our crusader does not have much more time in this world.", sourceObjective = "Request the aid of A'dal at Shattrath City in Terokkar Forest.", completion = "<A gentle ringing fills your head as you approach the naaru.>\n\nI know why you have come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13082] = { id = 13082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Boon of A'dal", description = "I am pleased that you have come to me, {name}. I know of Crusader Bridenbrad, and of your travels in hope of saving him. Bridenbrad's valor has sparked remarkable selflessness in you, and this is a miracle unto itself.\n\nThe Light will take care of its own. I will extend my blessing to Bridenbrad and he shall not endure the corruption of undeath. I shall return you to Dalaran, and you shall return to him. Know that I remain with you.", sourceObjective = "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown.", completion = "<As you approach Crusader Bridenbrad, you cannot help but notice that his skin has taken on a pale hue and his breaths are shallow. It is clear that he has little time left.>\n\nYou have returned to me, {class}. I must admit... it is good to see you again... your face renews my hope that this land will be free of Arthas's grasp one day soon. I'm proud to have met you...", sourceObjectiveStatus = "unverified-source-field" }
quests[13083] = { id = 13083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Within the Darkness", description = "<Crusader Bridenbrad's tabard rests in the bottom of the chest, shifting slightly as the howling wind finds its way in.>\n\nTirion will desire this last remnant of the great crusader.", sourceObjective = "Bring Crusader Bridenbrad's Tabard to Highlord Tirion Fordring at Crusaders' Pinnacle.", progress = "He has departed, hasn't he? I felt a small bit of light leave the land.", completion = "I am glad you were able to save him from undeath. With A'dal's blessing, he will know no evil in his afterlife.\n\nWe shall take heart in his shining example and in your selflessness. Thank you for all that you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13084] = { id = 13084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vandalizing Jotunheim", description = "Let us see if we can further weaken the resolve of the vrykul, {name}.\n\nEach day I wish you to travel to Jotunheim and put their banners to the torch. It may seem a trivial thing, but to see their ancestral home vandalized on a daily basis will demoralize them more than any physical punishment you can inflict.\n\nAt least... it can't hurt.", sourceObjective = "Duke Lankral at The Shadow Vault wants you to burn 10 Vrykul Banners.", completion = "<The duke looks at you a moment and nods.>\n\nYou're inflicting horrible mental trauma on the Jotunheim vrykul. This is where they were first reawakened. It is a place of significant importance to them, second only to Ymirheim.\n\nYou must keep up the pressure there while I hold the vault from the assault of the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13085] = { id = 13085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaelen Has Returned", description = "I just saw that incompetent fool, Vaelen the Flayed, sneak into the vault building.\n\nGo see to it that he rectifies his mistake and returns my death knights to me!", sourceObjective = "Speak with Vaelen the Flayed at The Shadow Vault.", completion = "I think I can guess why you're here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13086] = { id = 13086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Line Of Defense", description = "I've triggered the base's defenses, {class}! Atop each of the Vanguard's four towers is a retractable Argent Crusade cannon, blessed by Father Gustav himself. You'll need to fly up to one of those towers and man a cannon. Use it to destroy the Scourge onslaught that the Lich King has deployed.\n\nJust one warning, the Scourge will undoubtedly send their frost wyrms to lay siege to the towers. Shoot them out of the sky! If they destroy the walls and towers of this base, we're done for!", sourceObjective = "Use an Argent Cannon to destroy 100 Scourge attackers. You must also kill 3 Frostbrood Destroyers.\n\nReturn to Siegemaster Fezzik should you succeed.", progress = "The screams of the dying will haunt me forever! Help them!", completion = "You handled the cannon like a goblin gunner, friend. You've saved the Vanguard and the Argent Crusade - all the while backing the Highlord himself up on the field of battle! Amazing!", sourceObjectiveStatus = "unverified-source-field" }
quests[13087] = { id = 13087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "So what are ya doin' if you dinna have any stew for me.   I got me a HUNGER!   At least bring me some chilled meat so I kin cook me own stew!   If ya do, I kin give ya the recipe so you kin make it for yourself.   NOW GO GET ME SOME MEAT!", sourceObjective = "Bring four chilled meat to Brom Brewbaster at Valgarde.  chilled meat can be found on any Northrend beast.", progress = "WHERE IS MY MEAT!", completion = "Ya gots me meat!   Here is your recipe, I gots cookin to do!", sourceObjectiveStatus = "unverified-source-field" }
quests[13088] = { id = 13088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "We got a lot of new recruits here and these lads are hungry!  If you could go out and get me some chilled meat for stew, I could teach you how to make it for yourself.", sourceObjective = "Bring four chilled meat to Rollick Mackreel at Valiance Keep.  chilled meat can be found on any Northrend beast.", progress = "The lads need meat for their stew.", completion = "That will keep our recruits fed!   Here's how you cook it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13089] = { id = 13089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "Nothing like a stew made from the living to warm your bones.   Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.", sourceObjective = "Bring four chilled meat to Thomas Kolichio at Vengeance Landing.  chilled meat can be found on any Northrend beast.", progress = "The stew awaits...", completion = "We can quickly turn this flesh into stew.", sourceObjectiveStatus = "unverified-source-field" }
quests[13090] = { id = 13090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Cooking", description = "The warriors of the Warsong Offensive need food in their bellies to keep their strength up.   If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew.   I would be willing to teach you the recipe if you were willing.", sourceObjective = "Bring four chilled meat to Orn Tenderhoof at Warsong Hold.  chilled meat can be found on any Northrend beast.", progress = "When the meat is present, the stew will be prepared.", completion = "I give my thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13091] = { id = 13091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Being a Water Terror", description = "The water lock outside my cave is teeming with elementals that the vrykul magi have yet to tame. I am going to teach you a trick for possessing these creatures for a short time, and you will use them to wreak havoc upon Jotunheim!\n\n<The banshee-infested vrykul draws magic in the air and touches a large finger to your forehead.>\n\nGo now and open the gate to the lock. A water terror will rush out and you will possess it to destroy our enemies!", sourceObjective = "The Bone Witch in Njorndar Village wants you to possess a Water Terror and use it to slay 10 vrykul in the greater Jotunheim region.\n\nQualifying vrykul are Jotunheim Sleep-Watchers, Jotunheim Warriors, Mjordin Water Magi, Njorndar Spear-Sisters, and Valhalas Vargul.", progress = "My reading of the bones tells me that you're not quite done.", completion = "I have never seen such terror in the eyes of a vrykul. They think themselves masters of their world.\n\nYou and I are going to prove them wrong. Very wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[13092] = { id = 13092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Bones", description = "One of the benefits of possessing this creature is that I have access to all of her powers. As a bone witch and rune reader, she has the power to throw the bones and determine one's fate.\n\n<The Bone Witch smirks.>\n\nLucky for you and I that I have it within my power to influence those readings.\n\nBring me the bones of the vrykul that you kill here in Jotunheim and I will toss them to allow you to determine your own fate.", sourceObjective = "The Bone Witch in Njorndar Village has instructed you to collect 15 Vrykul Bones.", progress = "I find it remarkable that these beings ever held sway over the world when they utilized such primitive magic.", completion = "And now we shall see what the future holds for you.\n\n<The Bone Witch casts the bones upon the rug in front of her.>\n\nChoose your fate, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13093] = { id = 13093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reading the Bones", progress = "Bring me more vrykul bones and we will influence the fates in your favor.", completion = "Choose your fate, {name}." }
quests[13094] = { id = 13094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Horde adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", sourceObjective = "Image of Warmage Kaitlyn wants you to recover Berinand's Research.", progress = "Please, {name}, tell me you've found Berinand's research....", completion = "You found it!? Yes, yes, it's all here.\n\nPlease, take this with my gratitude. And if it's not too much to ask, it would be better for me if Berinand never learned of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[13095] = { id = 13095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have They No Shame?", description = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.\n\nI made the mistake of discussing it with a group of Alliance adventurers and now it's gone!\n\nIt must have been them. Please, recover the book.", sourceObjective = "Image of Warmage Kaitlyn wants you to recover Berinand's Research.", progress = "Please, {name}, tell me you've found Berinand's research....", completion = "You found it!? Yes, yes, it's all here.\n\nPlease, take this with my gratitude. And if it's not too much to ask, it would be better for me if Berinand never learned of this.", sourceObjectiveStatus = "unverified-source-field" }
quests[13096] = { id = 13096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "Did ya see it, mon?\n\nIt musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nI done took an oath not ta be gettin' involved here. My job be to observe only. But dis cannot stand! Gal'darah must pay!\n\nGo into Gundrak and seek him out. Come back to me when Akali's death been avenged, mon.", sourceObjective = "Tol'mar at Dubra'Jin wants you to slay Gal'darah in Gundrak.", completion = "Ya done it?! Gal'darah be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to that wretch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13097] = { id = 13097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way north of Gundrak to Dubra'Jin and speak with Tol'mar. He will be able to direct you further in this cause.", sourceObjective = "Har'koa wants you to speak with Tol'mar at Dubra'jin.", completion = "Lissen up, mon. Dere be dangerous work ta be done!", sourceObjectiveStatus = "unverified-source-field" }
quests[13098] = { id = 13098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Gundrak be doomed, mon.\n\nHistory be repeatin' itself before our eyes. When trolls be turnin' on their own gods, the end be certain. It just be a matter of time.\n\nPerhaps if we can record the events clearly, we might prevent future generations from traveling down da same path.\n\nIf you be havin' the courage, enter Gundrak and search for clues to what brought the Drakkari Empire to such an end as dis.", sourceObjective = "Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "<Bah'Kini scans the engraved tablets for a moment, then turns her attention back to you.>\n\nDese be authentic, {race}. I'll be placin' dem in their proper place in my collection.\n\nPerhaps we can finally be puttin' an end to dis behavior.", sourceObjectiveStatus = "unverified-source-field" }
quests[13099] = { id = 13099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from her post just west of Gundrak. Perhaps you could find the time to check in on her for me?", sourceObjective = "To'kini wants you to speak to Bah'kini at Dubra'Jin.", completion = "Long-time student? Hah!\n\nIf by long-time ya mean my whole life, den I suppose dat be accurate.\n\nTo'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!", sourceObjectiveStatus = "unverified-source-field" }
quests[13100] = { id = 13100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infused Mushroom Meatloaf", description = "We have an important order that needs to go out!  Orton Bennet in Curiosities & Moore needs a mushroom meatloaf.\n\nGet some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan.  When you're done, deliver the cooked meatloaf to Orton.", sourceObjective = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", progress = "Do you have any food for me?\n\nI never seem to be able to get away from the shop, even for a minute.", completion = "This looks great!  Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[13101] = { id = 13101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convention at the Legerdemain", description = "Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto!\n\nYou need to provide some Northern Stew and a Jug of Wine from the cheese shop \"One More Glass\" in central Dalaran.  The owner of the cheese shop owes me the wine and you should find it somewhere around the shop.\n\nBring the wine and stews to Arille.", sourceObjective = "Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", progress = "Where is my food, I will have conventioneers here any minute!", completion = "This is plenty of food for everyone!  I am sure the customers will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[13102] = { id = 13102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sewer Stew", description = "Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there.\n\nCollect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat.\n\n You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square.\n\nOnce the vegetable stew is ready, bring it to Ajay.", sourceObjective = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.\n\nOnce it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", progress = "I've got hungry people down here!  We need some stew.", completion = "This will be consumed in no time!   Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[13103] = { id = 13103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheese for Glowergold", description = "Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese.\n\nCollect cheese which is on the shelf at \"One More Glass\" in central Dalaran and half full wine glasses found on tables all over the city.  Pour the wine together into a bottle and serve it with the cheese to Ranid.\n\nWe don't think he will know the difference.", sourceObjective = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.\n\nBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", progress = "Have you seen a servant with my wine and cheese platter.   I am quite peckish!", completion = "Aha, this appears to be a fine vintage!", sourceObjectiveStatus = "unverified-source-field" }
quests[13104] = { id = 13104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", sourceObjective = "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", completion = "My knowledge of Scourge tactics is without equal.\n\n<The Ebon Watcher peers at you.>\n\nBefore the battle for Light's Hope Chapel, my knights and I served under the Lich King - his icy grasp controlling our every action. The light of dawn changed everything...", sourceObjectiveStatus = "unverified-source-field" }
quests[13105] = { id = 13105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Once More Unto The Breach, Hero", description = "The Vanguard is secure, ally. We have reclaimed the Valley of Echoes and taken down the web walls blocking entry to the Breach. Now is the time to strike at Scourgeholme and establish our presence inside Icecrown. The battlefront moves on!\n\nI have asked the Ebon Watcher for his assistance with our assault upon Scourgeholme. His intimate knowledge of the Scourge will be invaluable in our effort.\n\nGo now and report to him at the tent outside of the Breach, northwest of here.", sourceObjective = "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", completion = "Your power has grown, my faithful knight.\n\n<Highlord Darion Mograine peers at you.>\n\nVengeance is at hand, brother. Koltira aids the Horde upon the gunship, Orgrim's Hammer, while Thassarian assists the Alliance aboard the Skybreaker. The Ebon Blade will soon wash over Icecrown and leave the armies of the Lich King in ruin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13106] = { id = 13106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackwatch", description = "The Scourge has a large facility called the Fleshwerks, dedicated to producing abominations and flesh giants. If we can shut it down, we can deprive the Lich King of a large component of his armies.\n\nI've sent Darkrider Arly to the area. She has a small base, Blackwatch, on a ridge overlooking the Fleshwerks and to the west of Corp'rethar. I'm told the Argent Crusade is sending someone to coordinate their efforts there, but the darkrider will know what to do. Find and assist her.", sourceObjective = "Speak to Darkrider Arly at Blackwatch in Icecrown.", completion = "Good. We'll need all the help we can get. Olakin here is the Argent Crusade's contribution to our effort. Let's cut the chatter and get down to the business of denying the Scourge their armies of the flesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[13107] = { id = 13107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mustard Dogs!", description = "Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip.\n\nYou need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city.\n\nBring him his picnic basket so he can be ready to go see the big game.", sourceObjective = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.\n\nBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", progress = "I am almost ready to go, I just need the food and for my mates... er... my fellow mages to arrive.", completion = "Perfect!  I just hope the Dalaran Destroyers finally win one!", sourceObjectiveStatus = "unverified-source-field" }
quests[13108] = { id = 13108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nIf I have to rip him limb from limb myself, he soon shall pay for his wretched deeds.\n\nShould you meet with him before I do, the honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my blessing and gratitude.", sourceObjective = "King Jokkum in Dun Niffelem wants you to enter the Halls of Lightning and defeat Loken. You are then to return to King Jokkum with Loken's Tongue.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little {race}.\n\nPlease accept this gift in return for your loyal friendship.", sourceObjectiveStatus = "unverified-source-field" }
quests[13109] = { id = 13109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nAs their leader, I wish nothing more than for their hearts to be mended and our friendship with the Stormlord to be renewed. In your defeat of Fjorn, a step has been taken down that path. I would have you bring us a step further...\n\nIn the Halls of Lightning, one even greater than Fjorn sits in opposition to our existence. Volkhan will not rest until either he, or we, are no more.", sourceObjective = "King Jokkum at Dun Niffelem wants you to enter the Halls of Lightning and defeat Volkhan.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little {race}. In time, I am certain my people will grow to forgive Thorim.", sourceObjectiveStatus = "unverified-source-field" }
quests[13110] = { id = 13110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Dead", description = "Not all of our soldiers made it out of Scourgeholme. Many were slain and turned into twisted reflections of their former selves. Such is the way of the Scourge. For those damned souls, there is no eternal peace. We must provide their souls rest.\n\nTravel through the Breach into Scourgeholme and slay the skeletal reanimated crusaders. Sprinkle this holy water on their bones so that their spirits may be freed.", sourceObjective = "Father Gustav at the Valley of Echoes in Icecrown wants you to use Holy Water on the corpses of Reanimated Crusaders to free 10 restless souls.", progress = "It is a grim task, {name}, but it must be done.", completion = "The path of the righteous crusader is one beset by inequity and evil. To cut through the middle is the only salvation. You have done that on this day and much more.", sourceObjectiveStatus = "unverified-source-field" }
quests[13111] = { id = 13111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Lissen, mon.\n\nAt first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nWhile dis be true, dere be somethin' special about dese Drakkari. If what I learned be true, den inside Gundrak dere be a special golem - one like nuthin' created before!\n\nYa want adventure, mon? Go inside Gundrak and bring me back a piece from dat golem ta study.", sourceObjective = "Chronicler Bah'Kini at Dubra'Jin wants you to enter Gundrak and recover a piece of the Drakkari Colossus.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[13112] = { id = 13112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infused Mushroom Meatloaf", description = "Orton Bennet in Curiosities & Moore be needin' a mushroom meatloaf.\n\nGet ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook 'em in the meatloaf pan.  When ye be done, bring that meatloaf to Orton.\n\nIf only de council would let me serve me gnome specialty, I would show dem a real treat!", sourceObjective = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", progress = "Do you have something for me?  I so rarely get away from my shop.", completion = "Is this food from Awilo?  Can you promise me there isn't any gnome in it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13113] = { id = 13113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Convention at the Legerdemain", description = "Can you believe da horde has outlawed cannibalism...it just ain't right I tell ya!  I guess I should keep me mind on me work when we gots an order to fill.\n\nArille Azuregaze at the Legerdemain Lounge has many a guest a'comin to his place, mon.  You gots to be providin' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran.\n\nBring the wine and stew to Arille.", sourceObjective = "Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", progress = "Where is my food?  My guests will be here soon!", completion = "My guests should find this acceptable.  Just don't tell them it came from Awilo.", sourceObjectiveStatus = "unverified-source-field" }
quests[13114] = { id = 13114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sewer Stew", description = "We be havin' another order to fill.  Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don't have so much to eat, mon.\n\nHe asked for a vegetable stew as he didn't appreciate da gnome that was in the last stew I sent.  Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay.\n\nYou can be gettin' to da Forest from da portal chamber in da eastern corner of Runeweaver Square.", sourceObjective = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot.\n\nThen bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", progress = "Make sure there isn't any gnome in the stew this time!", completion = "Stew looks good.  Thanks for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13115] = { id = 13115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheese for Glowergold", description = "Ranid Glowergold in da Leatherworkers shop be havin' a need for wine and cheese.  Why he don't want some tasty gnome is beyond me.\n\nCollect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city.  Bring da wine and serve it with the cheese to Ranid.\n\nYou can call da wine a Wine Medley, mon'.", sourceObjective = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran.\n\nBring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", progress = "Have you seen a servant with my wine and cheese platter.  I am quite peckish!", completion = "This wine is quite amazing!  I must know where it's from.", sourceObjectiveStatus = "unverified-source-field" }
quests[13116] = { id = 13116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mustard Dogs!", description = "Da Archmage Pentarus likes to be watchin' his crazy battle ball game, but he be needin' some food for da game.\n\nYou be needin' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city.\n\nFill up his basket with the mustard dog goodies, mon'.", sourceObjective = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you be cookin' with your skill and 4 Wild Mustard that you find in the grassy areas of Dalaran.\n\nBring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", progress = "Make sure the wild mustard dogs are 100% rhino and have no Gnome in them!", completion = "Perfect!  I just hope the Dalaran Destroyers finally win one!", sourceObjectiveStatus = "unverified-source-field" }
quests[13117] = { id = 13117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Are They Coming From?", description = "The Lich King's tireless minions labor away night and day to assemble scores of abominations and flesh giants down there in the Fleshwerks.\n\nYet, that is not enough. More and more skeletal constructors keep appearing to increase the pace of work.\n\nIf we do not discover where they're coming from and how they're able to work so quickly, we'll be overrun before we can act in force. Search to the southeast and see if you can find the source of these skeletons.", sourceObjective = "Investigate a Summoning Altar in the eastern part of the Fleshwerks, then report back to Darkrider Arly at Blackwatch.", progress = "Have you found the source of the skeletons?", completion = "<You tell the darkrider about your discoveries at the summoning altar.>\n\nI suspected such. We can't let this continue. Our first priority is to destroy those summoning altars and then deal with the mess the Scourge has already created here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13118] = { id = 13118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purging Of Scourgeholme", description = "The Scourge have sent their armies at the Argent Crusade and have been repelled. What they do now is called a 'slash and burn.' All prisoners that they hold at Scourgeholme will be executed and raised as servants of the Lich King.\n\nUndoubtedly the Argent Crusade will request that you give their soldiers a proper farewell. I'll ask no such thing of you. To succeed we must kill Scourge indiscriminately.\n\nVenture to Scourgeholme, northwest through the Breach, and lay waste to all that stand in your way.", sourceObjective = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill 3 Forgotten Depths High Priests, 3 Forgotten Depths Underkings, and 8 Reanimated Crusaders.", progress = "Do not waste time, {name}.", completion = "You have done well, {name}. Keeping their numbers down will give the Argent Crusade the time that they need to set a foundation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13119] = { id = 13119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroying the Altars", description = "So they're summoning in their workers and warriors at those altars?\n\nThey'll need to be the first thing to go. The master summoner should have a staff which allows him to activate the portal. If you kill the master summoner and take the staff, you can use it to overload the summoning portal and destroy its altar.\n\nDo this at all four of the altars and return to me once they've been destroyed.", sourceObjective = "Kill Master Summoner Zarod and use his Summoning Stave to destroy the First, Second, Third, and Fourth Summoning Altars. When you've completed this task, report to Darkrider Arly at Blackwatch.", progress = "Are the summoning altars in ruins?", completion = "<Darkrider Arly nods in approval.>\n\nGood. Now, we can focus our efforts on shutting down the rest of the Fleshwerks.", sourceObjectiveStatus = "unverified-source-field" }
quests[13120] = { id = 13120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death's Gaze", description = "The Fleshwerks is a vast operation, and it will be difficult to keep an eye on all that transpires there. Fortunately, I have a plan.\n\n<Arly produces an orb from the folds of her cloak and shows it to you.>\n\nThis is a death's gaze orb. With it, we can observe the Scourge's actions and decide how best to strike.\n\nPlace these orbs on the stands at three crucial areas -- the abomination lab and the flesh giant lab to the southwest, along with the area surrounding the green cauldron far to the west.", sourceObjective = "Use the Death's Gaze Orb to place orbs on the Abomination Lab Orb Stand, the Flesh Giant Lab Orb Stand, and the Cauldron Area Orb Stand, then return to Darkrider Arly at Blackwatch.", progress = "Have you placed those orbs?", completion = "<Darkrider Arly closes her eyes and seems to focus on something far away.>\n\nWith the eyes of death itself, I watch our enemy. With this knowledge, we will utterly destroy them.", sourceObjectiveStatus = "unverified-source-field" }
quests[13121] = { id = 13121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Eye", description = "We must use the Lich King's tools against him if we are to decide our next step.\n\nOver the mountain to the southwest lies Kul'galar Keep. Within it reside the oracles of Jotunheim who receive orders from their master and scry upon others through the Eye of the Lich King.\n\nIt is the eye that you must fight your way to. While it cannot be used to pierce the veil within Icecrown Citadel, you should be able to use it to discern something of value so that we will know how best to proceed.", sourceObjective = "The Bone Witch in Njorndar Village has tasked you with using the Eye of the Lich King to gain information.", progress = "You return with no information at all! Is this how you repay my help to you and the Knights of the Ebon Blade?\n\nBegone and do not return until you have the knowledge which I seek!", completion = "Perfect! It's true that Iskalder is rumored to have been the finest vrykul warrior ever to live. And Vardmadra herself is going to come here to judge him!\n\nWe must move quickly if we are to get to this ancient hero before they do!", sourceObjectiveStatus = "unverified-source-field" }
quests[13122] = { id = 13122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scourgestone", description = "A Scourgestone is an item given to all Scourge upon birth or creation. It provides certain benefits to the holder, but more importantly it allows Scourge leaders visibility into the location and movement of all of their units.\n\nWith enough Scourgestones, I might be able to track the movement of other Scourge units across Icecrown.\n\nAs you slaughter Scourge in Scourgeholme, gather all of the Scourgestones that you find. Return to me when your bags are full.", sourceObjective = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to bring him 15 Scourgestones.", progress = "Scourgestones will help us find our enemy.", completion = "Now let me see if there's something that I can do with these stones to give us a little bit of insight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13124] = { id = 13124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Struggle Persists", description = "Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus.\n\nWe must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause.", sourceObjective = "Raelorasz wants you to rescue Belgaristrasz and his companions in the Oculus.", completion = "Listen well, {race}.\n\nYour work here has just begun!", sourceObjectiveStatus = "unverified-source-field" }
quests[13125] = { id = 13125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Air Stands Still", description = "You must defeat the lords of Scourgeholme if this place is to be free of the Scourge's grasp.\n\nSalranax the Flesh Render lords over the temple on the first tier of Scourgeholme. Nearby Salranax you'll find High Priest Yath'amon preaching at the spirit tower on the second tier. Underking Talonox holds court at the Pit of Fiends, up the high road.\n\nThese are formidable opponents and must be approached with caution. Use this war horn should you require aid. The death knights of Acherus will come.", sourceObjective = "The Ebon Watcher at the Valley of Echoes in Icecrown wants you to kill Salranax the Flesh Render, Underking Talonox and High Priest Yath'amon.", progress = "Finish them, {name}!", completion = "A hard fought victory, {name}! The lieutenants will be replaced, but at least for today the air about Scourgeholme stands still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13126] = { id = 13126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Unified Front", description = "From here, it will take our combined efforts to proceed.\n\nAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield.\n\nWe can each provide you with drakes from our respective flights to help you reveal him.", sourceObjective = "Belgaristrasz wants you to destroy 10 Centrifuge Constructs to bring down Varos' shield. You then must defeat Varos Cloudstrider.", progress = "So, it is done!", completion = "It is as I had hoped, {race}. We work well together.\n\nMay our continued cooperation be enough to overcome the challenges that yet await!", sourceObjectiveStatus = "unverified-source-field" }
quests[13127] = { id = 13127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage-Lord Urom", description = "Only one obstacle stands between us and our ultimate goal here. His name is Urom.\n\nHe guards the third ring above us. Beware his powerful conjurings, friend.\n\nBring him down. Make him pay for his treacherous allegiance to the enemy!", sourceObjective = "Belgaristrasz wants you to defeat Mage-Lord Urom in the Oculus.", progress = "Has Mage-Lord Urom been dealt with?", completion = "Victory is in reach, friend.\n\nFocus, for now comes the true test.", sourceObjectiveStatus = "unverified-source-field" }
quests[13128] = { id = 13128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wing and a Prayer", description = "The time has come to face Eregos.\n\nHe draws strength from the energies he is charged with defending - sipping from the well of the great aspect Malygos.\n\nHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Use them wisely and Eregos shall surely fall.", sourceObjective = "Belgaristrasz wants you to kill Eregos in the Oculus.", progress = "You've done it, haven't you? You bested Eregos!", completion = "<Raelorasz listens intently to your report.>\n\n{name}, this is most welcome news.\n\nNot since the onset of this conflict have we dealt a blow of this magnitude to the Lord of Magic.\n\nPlease, friend, accept the gratitude of our unified dragonflights.", sourceObjectiveStatus = "unverified-source-field" }
quests[13129] = { id = 13129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Head Games", description = "<Kurzel rips a long strip of material from her blouse and hands it to you.>\n\nHere, {race}, take this. Dip it in the remains of Novos the Summoner.\n\nWe're going to figure out what makes the Scourge leaders tick.", sourceObjective = "Kurzel wants you to use Kurzel's Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to her inside Drak'Tharon Keep.", progress = "Do you have the cloth?", completion = "Hopefully we can find somebody willing to examine this sample.", sourceObjectiveStatus = "unverified-source-field" }
quests[13130] = { id = 13130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone That Started A Revolution", description = "You may look at Scourgeholme now and see a rancid pit of decay, but one day it will be a place of glory and honor. Highlord Fordring has deemed it \"Justice Keep.\"\n\nAlas, even an impregnable fortress like Icecrown Citadel began with but a single stone. So begins our search for the stone to start a revolution.\n\nTravel to Crystalsong, south of here, and seek out the Unbound Thicket in the east. Once there gather crystalline heartwood from the thicket floor and elven masonry from the Ruins of Shandaral.", sourceObjective = "Crusade Architect Silas at the Valley of Echoes in Icecrown wants you to retrieve 10 Trunks of Crystalline Heartwood and 10 pieces of Ancient Elven Masonry.", progress = "Are you lost?", completion = "Heartwood by nature is resistant to disease, rot and plague. This heartwood, however, goes so far as to repel such things! The masonry, affected by the fallout of the Unbound Thicket, will work in much the same way.\n\nSoon we will break ground.", sourceObjectiveStatus = "unverified-source-field" }
quests[13131] = { id = 13131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Junk in My Trunk", description = "Just look at it! Me trunk never been so empty.\n\nMe mates jumped at the sight o' all that booty, and now look at 'em! Rattlin' bones, they be!\n\nSay, thar be plenty o' loot farther in, an' not the cursed kind I'll wager.\n\nFetch it fer me an' I'll be rewardin' ya handsomely, matey.", sourceObjective = "Brigg in Utgarde Pinnacle wants you to find 5 Untarnished Silver Bars, 3 Shiny Baubles, 2 Golden Goblets, and a Jade Statue.", progress = "How'd yeh fare in thar, matey?", completion = "Brilliant! Ye've gone and done it, matey.\n\nNow I can show me face to the Cap'n without fearin' fer me life, thanks be ta you and yer mates.\n\nHere's a little booty fer you in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13132] = { id = 13132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance Be Mine!", description = "Only luck spared me from the same fate as me mates.\n\nIn the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of 'em turn.\n\nThere was a big ol' fella watchin' with a whole mess o' guards. They were chantin' Ymiron... maybe killin' him will free me mates?", sourceObjective = "Brigg in Utgarde Pinnacle wants you to kill King Ymiron.", progress = "Ya find the one in charge here, {race}? Did ya make 'em suffer?", completion = "Splendid! Mebbe now me mateys be able ta rest in peace.\n\nHere ya go, lad. Don't let it be said that ol' Brigg weren't generous ta those who showed 'im a kindness.\n\nGood doin' business wit yeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[13133] = { id = 13133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find the Ancient Hero", description = "Quickly, {name}, head southwest to the Halls of the Ancestors!\n\nWithin you will find slumbering mjordin. Wake them until you find Iskalder. When you do, use this amulet upon him and bring him back to me.\n\nNow go. There is no time to waste!", sourceObjective = "The Bone Witch at Njorndar Village wants you to return with Iskalder.", progress = "Where is the ancient hero?\n\nWe do not have time to chat. Go to the Halls of the Ancestors and find him before it is too late!", completion = "He's a fine specimen and will serve us well.\n\nNow, we have to make sure to use him properly to trap Vardmadra!", sourceObjectiveStatus = "unverified-source-field" }
quests[13134] = { id = 13134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spill Their Blood", description = "The Scourge cannot create their flesh monsters without blood and embalming fluid to preserve the parts and keep them functioning. If we can deny them these materials, their army will fall apart and we can easily destroy their creations.\n\nThroughout the labs where the flesh giants and abominations are cobbled together, you will find vats of embalming fluid and large orbs filled with blood. Destroy these, and bring death to any who would stop you!", sourceObjective = "Darkrider Arly at Blackwatch wants you to destroy 5 vats of Embalming Fluid and 5 Blood Orbs.", completion = "<A dark, hollow laugh greets you as you report to the darkrider.>\n\nYou reek of victory, {name}, and that is good news, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[13135] = { id = 13135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Could Kill Us All", description = "Southeast of here, at the eastern reaches of Crystalsong Forest, is an area known as the Unbound Thicket. Within that thicket creeps all manner of life. One thing all of the affected creatures of the thicket share in common is their affinity for magical energy. Each of them holds pure, crystallized energy. Enough to kill us all should it ever destabilize!\n\nTravel to the Unbound Thicket and kill its denizens for crystallized energy. We need fuel and they need to die. We call that a \"win-win.\"", sourceObjective = "Crusade Engineer Spitzpatrick at the Valley of Echoes in Icecrown wants you to retrieve 8 pieces of Crystallized Energy.", progress = "Did you get the crystallized energy?", completion = "Ah, this is perfect. The bomber should be up and running in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13136] = { id = 13136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagged Shards", description = "You pulled this jagged, dark brittle shard from the body of a ghoul. The metal blade lacks a smooth edge, suggesting it was forged by an unskilled hand, or was broken from a larger piece.\n\nYou recall seeing similar shards embedded in the bodies of all the ghouls you've encountered at the Fleshwerks, leading you to wonder why their creators bothered to include the metal at all. Perhaps Crusader Olakin Sainrith would have some insight if you brought him the shards from several ghouls.", sourceObjective = "Bring 10 Jagged Shards to Crusader Olakin Sainrith at Blackwatch.", progress = "What is that vile thing?", completion = "<Olakin handles the shards of metal gingerly.>\n\nYou saw these on all of the ghouls down there? I've never seen anything like this in all my battles against the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13137] = { id = 13137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not-So-Honorable Combat", description = "Atop the tallest peak to the southwest overlooking Jotunheim is Battlescar Spire. It is a place of reverence for the vrykul, second only to Valhalas in terms of where they prefer to do honorable combat.\n\nWe shall visit not-so-honorable combat upon it.\n\nGather your companions and fly to the spire. When you are ready, light the signal fire and I will appear within the body of Iskalder.\n\nWe will fight, you will win, and Vardmadra is sure to come to witness the battle!", sourceObjective = "The Bone Witch in Njorndar Village wants you to defeat Iskalder upon Battlescar Spire.", progress = "You have yet to defeat the ancient hero!", completion = "I've put Vardmadra aside for the moment. She's someplace safe until we can enact our final revenge!", sourceObjectiveStatus = "unverified-source-field" }
quests[13138] = { id = 13138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Smelting... Smelting!", description = "<Olakin turns one of the shards over in an armored fist.>\n\nThese could pierce armor with enough force. We have to find out what they're made of and what the Lich King intends to do with them.\n\nTo the east, nestled next to Icecrown Citadel itself, lies Malykriss. From the few reports we have, it's full of smelting and smithing equipment. Bring these shards there, and smelt them in one of the open furnaces on the bottom level of Malykriss. Once the metal has been reformed, we can identify it.", sourceObjective = "Use the Bag of Jagged Shards near one of the bottom level Malykriss furnaces. Return to Crusader Olakin Sainrith at Blackwatch with the Smelted Metal Bar.", progress = "Have you smelted those fragments yet?", completion = "There is no doubt, this is raw saronite. We've seen weapons made from it in the hands of the Lich King's chosen before, but this is the first time it's been used to arm anything else. The scale of that mining operation must be huge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13139] = { id = 13139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Frozen Heart Of Northrend", description = "Silas and Spitzpatrick have signed off on the materials and fuel needed to begin construction of Justice Keep. Thanks to you and the Ebon Blade the Scourge presence within Scourgeholme has been decimated and their lieutenants have been defeated.\n\nI have chosen the site at which we will break ground, but first you must deliver my report to Highlord Tirion Fordring. We will begin our march into Icecrown on his command.", sourceObjective = "Deliver Father Gustav's Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", progress = "Stand easy, {name}. What have you to report?", completion = "Your assistance has been integral in securing the front. The first true victory of this war is close at hand - which is why our next step is the most crucial.\n\nRest assured, {name}, the Scourge will not give up without a fight. Your most difficult challenge awaits.", sourceObjectiveStatus = "unverified-source-field" }
quests[13140] = { id = 13140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runesmiths of Malykriss", description = "Those shards you recovered can only have come from one place, Malykriss. It's the seat of the Lich King's metalworking operations, to the east of Corp'rethar.\n\nWhat's puzzling is that metal isn't needed to stitch together abominations or flesh giants, or to summon skeletal servants. Find the skeletal runesmiths working on the bottom level of Malykriss and capture the plates they're working on. We need to find out why this metal is finding its way to the Fleshwerks.", sourceObjective = "Bring 5 Runed Saronite Plates to Crusader Olakin Sainrith at Blackwatch.", progress = "Were you able to capture those rune plates?", completion = "These plates match the shards almost exactly. They must be using cuttings from them to \"enhance\" the ghouls produced here. The Scourge is desperate enough to make a weapon of anything, it seems. All the more reason to hasten our destruction of this abominable place!", sourceObjectiveStatus = "unverified-source-field" }
quests[13141] = { id = 13141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For Crusaders' Pinnacle", description = "<Highlord Fordring holds a banner of the Argent Crusade.>\n\nThis banner is like no other, {name}. It carries with it a powerful blessing, able to sanctify large tracts of blighted land.\n\nYou must take it northwest, through the Breach, to an area the Scourge have mockingly named Crusaders' Pinnacle. Plant the banner atop the skulls of our fallen brethren at Crusaders' Pinnacle and defend it against attack. Once the land is sanctified, return to Father Gustav.\n\nGo now, {name}. Hold no fear in your heart.", sourceObjective = "Venture to Crusaders' Pinnacle and use the Blessed Banner of the Crusade atop the Pile of Crusader Skulls. Defend the banner against Scourge attack until the land atop the pinnacle is sanctified and then return to Father Gustav at the Valley of Echoes in Icecrown.", progress = "Have we broken ground?", completion = "Blessed Light! We have taken the pinnacle! Finally, construction of Justice Keep can begin. Highlord Fordring and the knights are already en route to our new base. You must meet them there, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13142] = { id = 13142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banshee's Revenge", description = "The time has come, {name}. You and your friends must challenge the lord of Balargarde Fortress, the master of Jotunheim, Overthane Balargarde.\n\nAtop the fortress, which is on the southwestern edge of Jotunheim, you will find a horn. Blow into it. Allow your challenge to resound throughout the steadfast.\n\nBalargarde will have no choice but to face you. And I... excuse me, Vardmadra will be there to adjudicate the challenge.\n\n<The banshee-possessed vrykul lets out a bellowing cackle.>", sourceObjective = "The Bone Witch at Njorndar Village has asked you to exact her revenge by challenging and defeating Overthane Balargarde.", progress = "Overthane Balargarde is not dead. Did you have problems finding his fortress?", completion = "Words cannot describe what I'm feeling at the moment, {name}. My revenge is complete and there is naught else for me to do.\n\nIf only I could be there when the Lich King is finally taken down.\n\nDon't fool yourself though, Jotunheim is far from 'dealt' with. I will remain in possession of this witch until such time as the vrykul are no longer a threat.\n\nLook around, there are many items of value in this cave. Take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[13143] = { id = 13143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Recruit", description = "First things first. I saw some Lithe Stalkers on the ramparts just east of us. They used to serve us before we broke with Arthas, and they're about as perfect a scout as you can get... with a little prodding from an eye of dominion.\n\nFly up, find one of the stalkers, beat it down a bit, and then use this Sigil of the Ebon Blade to command its obedience. It will recognize the sigil, guaranteed. Lead it back to the top of the rocks northeast of here and it will find its way to me.", sourceObjective = "Vereth the Cunning on the Rise of Suffering has requested that you bring a subdued Lithe Stalker to the top of the rocks northeast of the Rise of Suffering.", progress = "I'm sure their new masters don't go easy on them, but there's no way these things would forget the lessons we lashed into their skins. They'll fear those sigils for as long as they crawl this land.", completion = "I've chained the wretch to the post over there and I'll look into getting my hands on more of them.\n\nNow let's make some use of that eye.", sourceObjectiveStatus = "unverified-source-field" }
quests[13144] = { id = 13144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing Two Scourge With One Skeleton", description = "The workers in the Fleshwerks abomination lab have already completed a number of their creations. For now, the creatures are chained to the pillars around the edge of the lab, but if we do not act, they will march with the Lich King's armies.\n\nGrasping arms reach out of the bone piles spread throughout the Fleshwerks. These arms belong to skeletons enchanted with the power of fire. Find and free these skeletons, then take them near the completed abominations and watch the show!", sourceObjective = "Darkrider Arly at Blackwatch wants you to destroy 3 Chained Abominations with Burning Skeletons.", progress = "Have you destroyed the completed abominations?", completion = "Ah, good. There's nothing like the smell of roasted putrid flesh in the morning. That's the smell of victory over the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13145] = { id = 13145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vile Hold", description = "We need to know what we're up against.\n\nUse the eye of dominion to assume control of a lithe stalker and scout out the area. There are a few spots in particular I saw when flying in that I want you to get a closer look at: the overlook in the northeast, the work area in the southeast, the large forge near the center, and the ritual area in the southwest.\n\nThe stalker can leap far and won't be hurt by large falls - use that to your advantage to get up and down from those ramparts.", sourceObjective = "Vereth the Cunning at the Rise of Suffering has requested that you use a Lithe Stalker to scout out Malykriss.", progress = "Flying may be a bit more graceful, but there's no way that we could get in as close as the stalker can without being detected.", completion = "Excellent work. It seems more death knights remained loyal to Arthas than I initially thought.\n\nHe certainly is sparing nothing in his attempt to replace Acherus. A pure saronite citadel would be hard to destroy indeed. There's no need to destroy it though... we can halt production and put down these death knight leaders here and now, before they become a real threat.\n\nMost importantly, we need to disrupt them enough to get those death knights away from from the leaders so that we can make our strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[13146] = { id = 13146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Generosity Abounds", description = "We need to cause some disruption to bring those death knights away from their leaders. If we lay waste to their minions below, I suspect they'll have to devote more attention to keeping a close eye on operations.\n\nAbominations are easy prey - slow, predictable, and most importantly, stupid. Take advantage of their trust of the stalkers to drag them near some of the Scourge bombs scattered throughout the construction area. You'll be able to light the bombs far before they figure out what's going on.", sourceObjective = "Vereth the Cunning wants you to use the Lithe Stalker's Iron Chain to drag Scourge Bombs to 4 Lumbering Atrocities inside Malykriss.", progress = "Did they even see it coming?", completion = "They didn't even think to lay a hand on you, did they? At least they're predictable.", sourceObjectiveStatus = "unverified-source-field" }
quests[13147] = { id = 13147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matchmaker", description = "The major difference between vargul and lesser undead minions is that vargul still possess enough of their minds to despise being used for labor. Never will a vargul be pleased to be working aside skeletons or ghouls.\n\nLets take advantage of this inevitable animosity and start some fights between the umbral brutes and the other undead in Malykriss. That should serve to slow production and bring the death knights down to babysit.\n\nShould be simple - throw rocks at the brutes as they near lesser undead.", sourceObjective = "Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker to throw rocks at Umbral Brutes as they near lesser undead in Malykriss. Return after you've started 5 fights.", progress = "Predictable louts.", completion = "No need to sacrifice our own men when they are this easily manipulated, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[13148] = { id = 13148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necklace Repair", description = "This damaged necklace has an invoice with it that reads \"Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran\".\n\nPerhaps you should repair it and return it to him.", sourceObjective = "Repair the necklace with a single Chalcedony and return it to Timothy Jones in at the Jewelcrafters Shop in the Magus Commerce Exchange in Dalaran.", progress = "What brings you here?", completion = "How did you find this!   Many of these necklaces were looted from one of my shipments a few weeks ago!   Let me repay you with this Jewelcrafter's Token.", sourceObjectiveStatus = "unverified-source-field" }
quests[13149] = { id = 13149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispelling Illusions", description = "The infinite dragonflight seek to disrupt history by deceiving Prince Arthas.\n\nIf they can convince him that none of the grain here carries the plague, then he'll never have to make the fateful decision to cull Stratholme.\n\nUse this arcane disruptor on any suspicious crates of grain you find.", sourceObjective = "Chromie wants you to use the Arcane Disruptor on the suspicious crates in Stratholme Past, then speak to her near the entrance to Stratholme.", progress = "Well done, friend.\n\nArthas' forces have discovered the plagued grain.", completion = "You have done well, friend. The plagued grain was exposed to Arthas' troops.\n\nListen carefully, now. There remains more to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13150] = { id = 13150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDLost: Widget", description = "Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.   Perhaps if you fixed it and returned it to him, he would have a reward for you.", sourceObjective = "Repair the whatsit and return it to Timothy Jones at the Jewelcrafting shop in Dalaran.Attached to the bottom of the widget is an invoice that indicates the owner is \"Timothy Jones - Jewelershop Name, District Name\" in Dalaran.  Perhaps if you fixed it and returned it to him, he would have a reward for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13151] = { id = 13151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Escort", description = "Arthas will soon face a desperate dilemma, and make a momentous decision.\n\nI must call upon you to accompany the prince in his culling.\n\nArthas must make it through Stratholme alive and you must see to it that he defeats Mal'Ganis!", sourceObjective = "Chromie has asked you to accompany Arthas in the Culling of Stratholme. You are to speak with her again after Mal'Ganis is defeated.", completion = "You have done well, {name}.\n\nThe Infinites have been foiled and this thread of history remains intact.\n\nI thank you for your invaluable assistance, as does the entire Bronze Dragonflight.", sourceObjectiveStatus = "unverified-source-field" }
quests[13152] = { id = 13152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit to the Doctor", description = "So they've been embedding these ghouls with broken shards of saronite down in the Sanctum of Reanimation? We must put a stop to this, before these ghouls can be deployed against our troops.\n\nFind the entrance to the Sanctum of Reanimation in the flesh giant lab area of the Fleshwerks. There, the ghoul mastermind, Doctor Sabnok, keeps the most fearsome of his creations, Patches. Free Patches from his chains and help him take his revenge on the doctor. Let his own creation be his undoing.", sourceObjective = "Darkrider Arly at Blackwatch wants you to destroy the Metal Stake imprisoning Patches in the Sanctum of Reanimation and help him get his revenge on Doctor Sabnok.", progress = "Have you unleashed the doctor's creation against him?", completion = "<Dakrider Arly throws her head back and laughs darkly.>\n\nA fitting end for the 'good' doctor, wouldn't you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[13153] = { id = 13153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warding the Warriors", description = "{name}, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", sourceObjective = "Sorceress Kaylana at Wintergrasp Fortress wants you to retrieve 10 sets of Imbued Horde Armor from Horde players at the Glacial Falls.", progress = "So, did you find the armor?", completion = "Augh. It's still dripping. Couldn't you have at least dried it off first?", sourceObjectiveStatus = "unverified-source-field" }
quests[13154] = { id = 13154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", sourceObjective = "Bowyer Randolph at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.", progress = "How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", completion = "Excellent! This will help fuel the flames of war for days to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13155] = { id = 13155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereth the Cunning", description = "I've already heard some rumors regarding Malykriss and Arthas's new death knight order, but I assumed it nothing more than filling the void. These numbers suggest he's trying to take it up a notch though.\n\nWe dispatched one of our best to Malykriss not long ago - Vereth the Cunning. You should be able to find him on the Rise of Suffering, just west of Malykriss, and inside the Court of Bones.\n\nTry not to draw too much attention on your way in.", sourceObjective = "Report to Vereth the Cunning on the Rise of Suffering in Icecrown.", completion = "The Vile Hold... a testament to how much Arthas hates losing. Let's drive the blade deep.", sourceObjectiveStatus = "unverified-source-field" }
quests[13156] = { id = 13156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Herb", description = "My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!", sourceObjective = "Anchorite Tessa in Wintergrasp Fortress wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.", progress = "I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", completion = "Excellent! This will help protect our troops against the cold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13157] = { id = 13157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crusaders' Pinnacle", description = "Stand proud in knowing that it was you who helped establish the Argent Crusade inside the walls of Icecrown, {name}. The Crusaders' Pinnacle now stands in direct defiance of the Lich King and his twisted minions.\n\nHighlord Fordring and the crusaders who survived await your arrival at Crusaders' Pinnacle. Travel once more through the Breach and seek out the highlord!", sourceObjective = "Seek out Highlord Tirion Fordring at Crusaders' Pinnacle in Icecrown.", completion = "A long and arduous journey awaits us as we make our way to the gates of Icecrown Citadel. I, and the soldiers of the Argent Crusade, wish to thank you for all that you have done. We rest easier knowing that you will fight alongside us in this cursed place.\n\n<Highlord Tirion Fordring salutes.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13158] = { id = 13158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Warden Alturas at once. He'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", sourceObjective = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Warden Alturas.", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13159] = { id = 13159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment", description = "Here is the prison key.\n\nMy men and I will stay here as a last line of defense in the event that you are unable to overcome the assault.\n\nBe sure to speak with Lieutenant Sinclari. She'll provide you with access to the prison's defenses.\n\nHurry, {race}. There is little time. The few I left inside won't last long without your help. Report back to me once the invasion forces have been successfully dealt with.", sourceObjective = "Warden Alturas wants you to enter the Violet Hold and put an end to the blue dragon invasion force. You are to report back to him once Cyanigosa is slain.", progress = "Is it over? Were you able to withstand the assault?", completion = "The crisis is averted, then?\n\nThat is good news indeed. I will forward the news on to Rhonin.\n\nPlease, accept this with the gratitude of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[13160] = { id = 13160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning View", description = "Gargoyles make effective scouts and can be deadly if left to rain attacks from the air, but they have a very obvious weakness. Most of them have to go through long periods resting as stone to maintain the energy they need to carry their heavy bodies through the air.\n\nAs I peered through the eye you were using, I noticed dozens of iceskin sentries resting on the eastern and southern walls inside. Use the stalker to leap up to their ledges and devastate them while they sleep.", sourceObjective = "Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker's heave ability to destroy 12 sleeping Iceskin Sentries.", progress = "Almost too easy.", completion = "Not so much of a threat when they're sleeping.", sourceObjectiveStatus = "unverified-source-field" }
quests[13161] = { id = 13161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider of the Unholy", description = "It's time that we start cutting off the heads of the beast.\n\nI served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless.\n\nRokir's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious.\n\nBe nimble, {class}, and do not take him lightly.", sourceObjective = "Vereth the Cunning on the Rise of Suffering wants you to kill Rokir, the Rider of the Unholy.", progress = "Is it done?", completion = "The world will be a much better place without Rokir in it - trust me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13162] = { id = 13162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider of Frost", description = "Sapph... Sapph's a death knight like no other. She'll shower you with sweet words and you'll swear that she has no evil within her heart, and then she'll run you through without even breaking her smile.\n\nI have no fear that you'll be able to best Sapph, but do not grow overconfident. Her strength lies in lulling her victims into a false ease, shortly before shattering them with a fierce barrage of frost attacks.\n\nDo not let your guard down, and do not underestimate her.", sourceObjective = "Vereth the Cunning on the Rise of Suffering wants you to kill Sapph, the Rider of Frost.", completion = "I can't deny, I'll miss her laugh... and that smile that would creep onto her face just before she killed someone. A little less need to watch my back though, so I suppose I can't complain.", sourceObjectiveStatus = "unverified-source-field" }
quests[13163] = { id = 13163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider of Blood", description = "Baelok is one of the few vrykul that I've ever seen rise through the ranks, and that was mostly accomplished through sheer brutality. If your competition ends up dead, there's far less to compete against.\n\nWhen you join battle with him, spread out from your companions and keep your distance as much as you reasonably can. He will not hesitate to steal your life force for himself, so you will need to hinder his ability to do so as much as possible.\n\nYou have my confidence. See to it that he dies.", sourceObjective = "Vereth the Cunning on the Rise of Suffering wants you to kill Baelok, the Rider of Blood.", progress = "Is he dead?", completion = "So he finally lost? Good to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[13164] = { id = 13164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Bloodbane", description = "With the riders of the Host of Suffering dead, now is the time to put an end to their true leader: Orbaz Bloodbane.\n\nMograine caught up with me while you were off and told me that he found where Orbaz is hiding. Under Icecrown Citadel itself, there is an immense pit - you will find Orbaz just outside its lip.\n\nSome of the Ebon Blade's strongest agents have already been dispatched - gather aid and join the fight. It is time for Bloodbane to die.", sourceObjective = "Vereth on the Rise of Suffering has dispatched you to kill Orbaz Bloodbane.", completion = "Mograine himself arrived to see the deed done then? I imagine there was some ill blood between those two - no surprise that he wanted a piece of the wretch.\n\nYou've done exceedingly well, {race}, and you shall be awarded appropriately. The Ebon Blade thanks you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13165] = { id = 13165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Acherus", description = "The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father's cursed soul: my last memory as a free man.\n\nWe must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, {name}. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!", sourceObjective = "Use your Death Gate spell to return to Acherus: The Ebon Hold. Report to Highlord Darion Mograine once you arrive.", completion = "The Lich King has returned to Northrend, wounded by the Ashbringer, but the second floor still holds the last of his armies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13166] = { id = 13166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Ebon Hold", description = "The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.\n\nUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!\n\nGo, {name}. You have my strength to carry you!", sourceObjective = "Slay 10 Scourge and help kill Patchwerk. Return to Highlord Darion Mograine should you succeed.", progress = "Acherus will be ours!", completion = "Well done, {class}. The remaining Scourge will be dealt with in short order and the rebuilding process will begin anew.\n\nI have but one last task for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13167] = { id = 13167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud underland of Azjol-Nerub.\n\nSince his betrayal, he has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who, like their leader, have pledged themselves to serving the Lich King.\n\nBring an end to the traitor king's reign, {class}. You will be doing a great service to both of our peoples.\n\nIf you manage to succeed where all others have failed, bring me the husk of Anub'arak.", sourceObjective = "Kilix the Unraveler in the Pit of Narjun has tasked you with defeating Anub'arak in Azjol-Nerub. You are to return to Kilix with Anub'arak's Broken Husk.", progress = "Is it done, {class}? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Kilix's eyes as he stares at the husk.>\n\nIt is DONE!\n\n{race}! Your name shall be recorded in the history of our people.\n\nI am in your debt....", sourceObjectiveStatus = "unverified-source-field" }
quests[13168] = { id = 13168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Gifts", description = "Look what we have here... eyes of dominion. The Cult normally goes to great lengths to keep these things safe, but I suppose their options for retreat are few when we're slaughtering them in their own home.\n\nThe eyes allow a being of any relative power to control an undead minion's actions precisely. As you can imagine, this can be extremely useful when it comes to your typical clumsy ghoul or skeleton.\n\nCare to try your hand at it? Use one of the eyes to control a captured shade.", sourceObjective = "Keritose Bloodblade at the Shadow Vault wants you to use an Eye of Dominion to take control of a captured Eidolon Watcher.", progress = "The options of subterfuge made available to us with the eyes are obvious. These will be very useful tools.", completion = "Nothing to it, eh? Any intelligent being should have little trouble controlling lesser undead. I suspect only the likes of a true necromancer could use these to seize control of any of the more powerful undead. That won't be a problem though - I can already think of quite a variety of destruction we can wreak with even the most paltry minions.\n\nShall we have at it then?", sourceObjectiveStatus = "unverified-source-field" }
quests[13169] = { id = 13169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Undead's Best Friend", description = "As is usual practice, the undead at the saronite quarry to the southwest starve plaguehounds to keep them extra aggressive. Use the shade to get up close and feed some of those hounds and I promise you they'll be content to leave you alone, if not side with the hand that fed them.\n\nDon't get too close to those things until you've fed them though. Their noses don't fall victim to your shade's elusiveness.", sourceObjective = "Keritose Bloodblade at the Shadow Vault wants you to use the Eidolon Watcher to feed 18 Hungering Plaguehounds.", progress = "No need to be wasteful - those hounds will serve whoever bothers to feed them.", completion = "Put them right to sleep, didn't it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13170] = { id = 13170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor is for the Weak", description = "Ghouls are fragile things when it comes down to it, and the lookouts at the saronite quarry down the path to the southwest are no exception. Using one of the shades, I have no doubt that you can sneak up and put down their lookouts without making a sound.\n\nClear out as many lookouts as you can reach in a reasonable amount of time... we'll want their ranks thinned for our assault to come.", sourceObjective = "Keritose Bloodblade at the Shadow Vault would like you to assassinate 20 Restless Lookouts.", completion = "Without even getting your hands dirty.", sourceObjectiveStatus = "unverified-source-field" }
quests[13171] = { id = 13171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Whence They Came", description = "My main concern is the saronite quarry down the path to the southwest. They are pulling up immense amounts of ore from that quarry and I'd like to know what they're building with it. To that end, we'll start by weakening their defenses.\n\nI noticed a series of crystals scattered throughout the base and I assume they are defensive structures of some sort, not unlike ziggurats. Use the eidolon watcher to destroy any of those crystals that you find.", sourceObjective = "Keritose Bloodblade at the Shadow Vault has sent you to banish 10 Scourge Containment Crystals.", progress = "Are those crystals out of the way? I don't want them to prove a nasty surprise for my gryphons.", completion = "Excellent work. We should have little threat in the air then.", sourceObjectiveStatus = "unverified-source-field" }
quests[13172] = { id = 13172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Chaos", description = "Effective tool, is it not? Excellent job weakening their defenses, {class}. Now we can push the main assault.\n\nThe plan here is straight-foward - we're looking to destroy anything moving, and get in there and steal some information amidst the confusion.\n\nLet me know when you're ready and I'll set you up with a skeletal gryphon.", sourceObjective = "Keritose Bloodblade at the Shadow Vault has dispatched you to slaughter 80 undead in the Weeping Quarry. Speak to him to secure a skeletal gryphon for the assault.", completion = "Practically defenseless. It doesn't get much easier than that.", sourceObjectiveStatus = "unverified-source-field" }
quests[13173] = { id = 13173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst the Confusion", description = "We got our hands on quite a few workers. They should do nicely.\n\nI want you to use an eye to bring one of these workers back into the quarry. With the entire camp in disarray, there's no way they'll be able to distinguish you from any of the other workers that were scattered by the assault.\n\nFind whoever is in charge of the operation and get to work. With any luck, we'll find out where that Saronite is being shipped off to pretty quickly. I'll watch over your shoulder through the eye." }
quests[13174] = { id = 13174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst the Confusion", description = "Shutting down their operation is just half of the plan. The other important goal here is to find out where all that saronite is being sent. We know of a few places it's been ending up, but the amount they're pulling out suggests to me that there's a bigger project in the works.\n\nOnce you're inside the quarry, get your hands on any of their documents that you can find. If you're assaulting the place with one of the gryphons, you can drop down from it as soon as the wetwork is done.", sourceObjective = "Keritose Bloodblade at the Shadow Vault has requested a Weeping Quarry Document, a Weeping Quarry Ledger, a Weeping Quarry Map, and a Weeping Quarry Schedule.", progress = "Did you bring back what I requested?", completion = "Let's see here... what do we have...\n\n<Keritose buries his head in the papers for a bit, seemingly gleaning little that he did not already know. Suddenly he finds what he is looking for...>\n\nMalykriss! The Vile Hold. It seems Arthas did not take the loss of his death knights so well... I'm not exactly sure what he's doing with all of that saronite, but I have a feeling he might be overcompensating for something.\n\nThat boy is not used to losing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13175] = { id = 13175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regaining Control" }
quests[13176] = { id = 13176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing the Delivery" }
quests[13177] = { id = 13177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Merciless", description = "Welcome to the Wintergrasp Fortress, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", sourceObjective = "Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.", completion = "Glorious! Truly, you are among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13178] = { id = 13178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay them all!", description = "Welcome to the Wintergrasp Fortress, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", sourceObjective = "Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.", completion = "Lok'tar! Victory for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13179] = { id = 13179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Merciless", description = "Welcome to the Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", sourceObjective = "Commander Zanneth in Wintergrasp wants you to slay 10 members of the Horde.", completion = "Glorious! Truly, you are among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13180] = { id = 13180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay them all!", description = "Welcome to the Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", sourceObjective = "Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.", completion = "Lok'tar! Victory for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13181] = { id = 13181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", sourceObjective = "Win a Wintergrasp battleground match and return to Tactical Officer Abrahmis in Wintergrasp. You must have participated in the battle to be credited for the victory.", completion = "Just what I wanted to hear!  A victory in Lake Wintergrasp - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13182] = { id = 13182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them even greater numbers.\n\nIt would do little good for the caverns to be cleansed of the undead that stain them if these fouled eggs were left to hatch and take their place.\n\nAs you  explore the expanse that was once Azjol-Nerub, be sure to clear our ancient home of any scourge eggs you find.", sourceObjective = "Kilix the Unraveler in the Pit of Narjun wants you to enter Azjol-Nerub and destroy 6 Nerubian Scourge Eggs.", completion = "It saddens me to see that things have come to this. If only we could return our great empire to what it once was...", sourceObjectiveStatus = "unverified-source-field" }
quests[13183] = { id = 13183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", sourceObjective = "Win a Wintergrasp battleground match and return to Tactical Officer Kilrath in Wintergrasp. You must have participated in the battle to gain credit for the victory.", completion = "It is a truly great thing you have accomplished this day. Be recognized for your sacrifice!", sourceObjectiveStatus = "unverified-source-field" }
quests[13184] = { id = 13184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outliving Usefulness" }
quests[13185] = { id = 13185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Siege", description = "I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.", sourceObjective = "Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.", completion = "Good job. Murp wish he was there to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13186] = { id = 13186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Siege", description = "It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.", sourceObjective = "Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.", completion = "Excellent. That should slow down their assault.", sourceObjectiveStatus = "unverified-source-field" }
quests[13187] = { id = 13187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Faceless Ones", description = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground.\n\nThey inadvertently exposed minions of the Old Gods known only as the Faceless.\n\nIn the end, we could not fight a war on two fronts.\n\nWith your aid, perhaps the Faceless will finally fall.", sourceObjective = "Seer Ixit in Ahn'Kahet wants you to kill Herald Volazj and the three Forgotten Ones that accompany him.", progress = "Have you overcome the faceless ones, {class}?", completion = "You have done well, {class}.\n\nMay your deeds renew hope for our people, that someday we may reclaim the city of our ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[13188] = { id = 13188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Kings Walk", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Alliance.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.\n\nOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Varian Wrynn. Use the portal.", sourceObjective = "Deliver the letter to King Varian Wrynn of the Alliance at Stormwind Keep in Stormwind City.", progress = "You have mere moments to live.", completion = "<Varian stares off into the distance.>\n\nIndeed old friend... Blood and honor.\n\n<Varian affixes his gaze upon you.>\n\nWere it not for this letter from Tirion, you would be a stain upon my floor. Only an endorsement from one of the greatest paladins to ever live could have ensured your survival.\n\nWe... We will work together against the Scourge. Against the Lich King!\n\nGLORY TO THE ALLIANCE!", sourceObjectiveStatus = "unverified-source-field" }
quests[13189] = { id = 13189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Blessing", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Horde.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.\n\nOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to the Warchief. Use the portal.", sourceObjective = "Deliver the letter to the Warchief of the Horde at Orgrimmar.", progress = "An interesting turn of events.", completion = "Eitrigg is alive because of this paladin. He would have been executed had Lord Fordring not broken him out of Stratholme.\n\nTirion Fordring, to have sacrificed everything to save the life of an orc... I have ever only known one other human to make such a sacrifice.\n\n<Thrall blinks back a tear.>\n\nYou will be in my heart always, Taretha.\n\nYes. For Tirion Fordring and for Eitrigg! We will accept you as a member of the Horde and your order as allies.\n\nBlood and honor! For the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13190] = { id = 13190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Things in Good Time", description = "Ahn'kahet, from whence we came...\n\nOne day, I dream, we shall overcome the death and darkness that hold our ancient home in their grip. To that end, I have a plan to weaken the resolve of our enemies.\n\nTheir precious Watchers must burn!\n\nTake their corpses and place them upon the brazier deep within the city. The scent of their burnt remains will linger in the air, reminding our enemy of their weakness.\n\nBe mindful, {class}! Their undead corpses are most fragile and will deteriorate rapidly.", sourceObjective = "Kilix the Unraveler in the Pit of Narjun wants you to obtain an Ahn'kahar Watcher's Corpse and place it upon the Ahn'kahet Brazier in Ahn'kahet.\n\nThis quest can only be completed on Heroic Difficulty.", progress = "Were you able to burn a Watcher's corpse, {race}?", completion = "Ahah!\n\nMay the mocking scent of failure eat at their empty souls!\n\nThank you, {class}. Today, you have struck a blow against the unliving.", sourceObjectiveStatus = "unverified-source-field" }
quests[13191] = { id = 13191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may be over, we must prepare for the Alliance's next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", sourceObjective = "Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", completion = "Excellent! This will help us defeat the Alliance in the battles to come!", sourceObjectiveStatus = "unverified-source-field" }
quests[13192] = { id = 13192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warding the Walls", description = "Hey 'mon. This place be givin' me dah heebie jeebies, don't cha know?\n\nWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", sourceObjective = "Hoodoo Master Fu'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls.", progress = "Did ya bring da armor, mon?", completion = "Ooh, ya dats da stuff, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[13193] = { id = 13193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", sourceObjective = "Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.", progress = "Back so soon? Drat, I was hoping to catch a moment's rest.", completion = "Well, I guess its another night of sharpening bones for me. Why didn't I stay in Silvermoon City like my brother?", sourceObjectiveStatus = "unverified-source-field" }
quests[13194] = { id = 13194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing with Roses", description = "Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.\n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might have one.", sourceObjective = "Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.", progress = "Were you able to recover the herbs? The sick and wounded increase by the hour.", completion = "Thank you, this will go far to treat our soldiers' wounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[13195] = { id = 13195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Herb", description = "My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!\n\nYou may also find one on a lasher in the area.", sourceObjective = "Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.", progress = "I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", completion = "Excellent! This will help protect our troops against the cold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13196] = { id = 13196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", sourceObjective = "Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.", progress = "How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", completion = "Excellent! This will help fuel the flames of war for days to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13197] = { id = 13197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "{name}! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We must prevent them from holding the keep!", sourceObjective = "Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?", completion = "Excellent! This will help fuel the flames of war for days to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13198] = { id = 13198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warding the Warriors", description = "{name}, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", sourceObjective = "Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls.", progress = "So, did you find the armor?", completion = "Augh. It's still dripping. Couldn't you have at least dried it off first?", sourceObjectiveStatus = "unverified-source-field" }
quests[13199] = { id = 13199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", sourceObjective = "Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.", progress = "Back so soon? Drat, I was hoping to catch a moment's rest.", completion = "Well, I guess its another night of sharpening bones for me. Why didn't I stay in Silvermoon City like my brother?", sourceObjectiveStatus = "unverified-source-field" }
quests[13200] = { id = 13200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", sourceObjective = "Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", completion = "Excellent! That should put a dent in their war machines!", sourceObjectiveStatus = "unverified-source-field" }
quests[13201] = { id = 13201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing with Roses", description = "So many of our braves were lost during the battle, but even more shall die if left untreated. \n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might be in bloom.", sourceObjective = "Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.", progress = "Were you able to recover the herbs? The sick and wounded increase by the hour.", completion = "Thank you, this will go far to treat our soldiers' wounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[13202] = { id = 13202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jinxing the Walls", description = "Hey 'mon. See dem Alliance sitting comfy in their keep?\n\nI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", sourceObjective = "Hoodoo Master Fu'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls.", progress = "Did ya bring da armor, mon?", completion = "Ooh, ya dats da stuff, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[13203] = { id = 13203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift" }
quests[13204] = { id = 13204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funky Fungi", description = "A misshapen piece of mushroom-like fungus falls from a particularly smelly, ooze-covered patch of the cave beast's flesh. Examining it, you are violently repulsed by its overwhelming stench.\n\nYou wonder to yourself if this is the kind of thing that the nerubians might find appetizing. Placing the sticky organism in your pack, you determine to find out...", sourceObjective = "You are to collect 6 Grotesque Fungus from Savage Cave Beasts in Ahn'kahet and deliver them to Kilix the Unraveler in The Pit of Narjun.", progress = "What in creation are these?!", completion = "Do you have any idea what you've been carrying around, {class}?\n\nThe cave beasts you've been harvesting have no traditional method of excreting their waste. You might want to wash your hands...\n\nThank you for the thought, but if you come across any more of these please keep them for yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[13205] = { id = 13205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty!\n\nI've felt their edge personally, and there be somethin' unnatural about 'em. Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nGet into their stronghold and if nuthin' else, pilfer some o' them weapons! Mebbe we can learn us a thing 'er two about 'em, mebbe not.\n\nBottom line - the fewer axes they be swingin' around, the better.", sourceObjective = "Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck...", sourceObjectiveStatus = "unverified-source-field" }
quests[13206] = { id = 13206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "We must discover the secret to these savages' weapons!\n\nIf you'd have seen how easily they cut through my companions, you'd understand my sense of urgency.\n\nScour the place. Gather all of their arms that you can carry.", sourceObjective = "Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to her inside Utgarde Keep.", progress = "What have you got there, {class}?", completion = "Marrah has informed us of the superiority of the Vrykul's weaponry. We'll have a look at these and see if there's anything to learn.\n\nTake this for your trouble, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13207] = { id = 13207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Stone", description = "Well now, I'm surprised to see other adventurers in a place such as this.\n\nIf my research on these halls is accurate, there be monumental discoveries to be made here!\n\nAssumin' I can count on ya to watch my back, you're welcome to tag along.", sourceObjective = "Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone.", progress = "Well, now, it turned out ta be a good thing we ran into each other after all.", completion = "Always more questions than answers, eh, lad?", sourceObjectiveStatus = "unverified-source-field" }
quests[13211] = { id = 13211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Fire Be Purged", description = "The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!\n\nThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.", sourceObjective = "Crusader Olakin Sainrith at Blackwatch wants you to burn 7 Festering Corpses using Olakin's Torch.", completion = "<Crusader Olakin Sainrith listens solemnly to your report.>\n\nIt is not the burial they deserved, but it is better than nothing, and better for those who yet live. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13212] = { id = 13212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Gone to Pieces", description = "With the abduction of Crusader Olakin, the Argent Crusade's forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won't see it that way.\n\nI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin's body parts.", sourceObjective = "Recover Olakin's Torso, Olakin's Legs, Olakin's Left Arm, and Olakin's Right Arm and bring them to Darkrider Arly at Blackwatch.", progress = "Have you recovered the, uh, remains of Crusader Olakin?", completion = "Well, I suppose it's good that we've \"recovered\" the crusader, though I doubt his comrades had this in mind. Let's see what we can do to get him back on his feet so we can get this charade over with and complete our mission here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13213] = { id = 13213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas", description = "I see and hear many things, {name}, and something very important has happened since your defeat of Overthane Balargarde: you are wanted for battle in Valhalas!\n\nYou will find the battle pit to the north. Go now with your friends and speak with Geirrvif the val'kyr. The challengers that she will offer you within Valhalas are sure to require their help.\n\nGood luck.", sourceObjective = "Speak with Geirrvif in Valhalas.", completion = "You have bested our finest warriors. Your name is renowned, {name}.\n\nPerhaps you think that this concerns me: it does not. If they can fall to you then they are not worthy and should be nothing but lowly vargul!\n\nBut perhaps I can give you and your friends different sport. Valhalas is also a place for combat of all types with many different kinds of foes.\n\nSpeak to me again when you and your friends are ready to proceed. We shall see if you are truly worthy.", sourceObjectiveStatus = "unverified-source-field" }
quests[13214] = { id = 13214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Fallen Heroes", description = "If you believe yourself ready to begin then I have just the match for you to cut your teeth on.\n\nAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.\n\nIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.", sourceObjective = "Geirrvif at Valhalas has challenged you to, in a single combat, defeat all six of the fallen heroes: Eldreth, Geness Half-Soul, Jhadras, Masud, Rith, and Talla.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "New blood.\n\n<The vrykul death knight spits on the ground at your feet.>\n\nYou all think that you have what it takes to fight here.\n\nYou are nothing before the might of the vrykul and the Scourge!\n\nStill, you did manage to defeat six incompetent corpses, so you must have some skill in you. Not likely enough for the next challenge though.", sourceObjectiveStatus = "unverified-source-field" }
quests[13215] = { id = 13215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Khit'rix the Dark Master", description = "A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.\n\nKhit'rix the Dark Master is one such.\n\nHailing from deep within the ground where insanity reigns, Khit'rix has asked for someone exotic to face in the ring. You will do.\n\nDare you face this Nerubian nightmare, {race}?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Khit'rix the Dark Master.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "You want me to be impressed by the fact that you and your friends were able to bring down a lone Nerubian priest?\n\nGet out of my sight before I summon my ghouls upon you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13216] = { id = 13216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: The Return of Sigrid Iceborn", description = "An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?\n\nNo matter, she certainly remembers you. She's insisting upon a chance to prove herself once more.\n\nPersonally, I think it's more a chance for revenge, but that too can be useful in this place.\n\nI leave it up to you, {name}. Will you face Sigrid Iceborn once more?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Sigrid Iceborn.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "The defeat of one of the hyldnir is mildly impressive, {race}, but you did have the help of your friends.\n\nYou're lucky that her drake didn't get involved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13217] = { id = 13217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Carnage!", description = "You've been successful up to this point, {name}, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.\n\nI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King's most fiendish minds.\n\nI do not see how you and your friends will defeat it. However, the choice is yours.", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Carnage.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "I'm starting to respect your prowess in the ring, {name}. Now I really don't like you.\n\nI would much rather have preferred to see you and your friends stuck to the bottom of that flesh giant's foot!", sourceObjectiveStatus = "unverified-source-field" }
quests[13218] = { id = 13218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Thane Deathblow", description = "Your skills have not gone unnoticed by the vrykul of Jotunheim, {name}. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.\n\nIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg's nickname is The Deathblow. I think you can guess how he earned it.\n\nDo you accept the thane's challenge?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Thane Banahogg, the Deathblow.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "I don't know what trickery it was that you used to bring down the thane -- I couldn't see it from this angle -- but I can assure you that you will not survive your next match.\n\nYes, I know who it is. Run, little {race}. Flee to the far corners of the world.\n\nOr stay and die. It matters little to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13219] = { id = 13219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Final Challenge", description = "I'm afraid that your success is going to be your undoing, {name}.\n\n<If the val'kyr could turn more white, she would.>\n\nWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.\n\nPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.\n\nWhat will you do? He's on his way. Will you face the blood prince in final battle?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Prince Sandoval.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", progress = "I laugh at you. I knew that it would come to this in the end.\n\nNo matter what you do, no matter where you run, Prince Sandoval will find you!", completion = "Your defeat of Prince Sandoval sickens me. An unwashed peasant such as yourself should have willingly given over his life simply for the chance to meet him and kneel at his feet.\n\nYou've earned your damned reward. Be quick about your choosing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13220] = { id = 13220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Olakin Back Together Again", description = "We can't afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.\n\nNear the Fleshwerks' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor's cleaver. Then, take Olakin's remains to the large slab in the middle of the sanctum and get to work.", sourceObjective = "Obtain a Spool of Thread and the Doctor's Cleaver, then take them to the Sanctum of Reanimation Slab and use Olakin's remains to attempt to reanimate the crusader. Return to Darkrider Arly at Blackwatch when this task is complete.", progress = "Have you put our brave crusader back together?", completion = "Olakin should consider himself fortunate. No one is rescued from the Scourge, no one. No amount of thread and heroism will save him a second time. I'll make certain he remembers it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13221] = { id = 13221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", sourceObjective = "Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.", completion = "Thank the Light. I'd thought Father Kamaros dead, or worse. Through your bravery and compassion, you have restored a great ally to the Argent Crusade. You have my thanks and those of the crusade.", sourceObjectiveStatus = "unverified-source-field" }
quests[13222] = { id = 13222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Siege", description = "Front and center, {name}! We're beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We'll show them the power of Gnomish technology and smash their walls to bits!\n\nHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.", sourceObjective = "Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures.\n\nPlayers of private rank or higher can build siege devices at Goblin Workshops.", completion = "That should show them the power of Gnomish invention!", sourceObjectiveStatus = "unverified-source-field" }
quests[13223] = { id = 13223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Siege", description = "Dem Alliance won't be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.\n\nYou, {name}! You go in Murp's place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is!", sourceObjective = "Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.\n\nSiege devices can be built by ranked Horde players at the Goblin Workshops.", completion = "Good job. Murp wish he was there to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13224] = { id = 13224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrim's Hammer", description = "The Argent Crusade pulled my ravaged body from the Broken Front. What a glorious battle, {race}. My axe sang as it cut down Alliance filth and Scourge alike.\n\nMy time is over. It will be a good death. Carry a message for me, soldier.\n\nOur base flies out of reach of Scourge - overhead between Mord'rethar and Aldur'thar. It is called \"Orgrim's Hammer.\"\n\n<Hork futilely attempts to salute.>\n\nFly high and avoid the Alliance juggernaut, Skybreaker. Tell Korm... tell him I died... fighting... For the Horde.", sourceObjective = "Seek out Sky-Reaver Korm Blackscar aboard Orgrim's Hammer flying above Icecrown.", completion = "<Korm salutes.>\n\nDamn the Scourge and damn the Alliance! Hork was one of our best. We will have our revenge. For Hellscream and for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13225] = { id = 13225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skybreaker", description = "We were neck deep in Scourge and Horde. The screams of the dying covered that field. It was torturous... unrelenting!\n\nAt some point my body gave out. I fell, only to be awoken by the Argent Crusade. They pulled me out of the Broken Front and brought me here. I'm not going to make it. Grant a dying soldier one last wish, {race}? Our base, the Skybreaker, flies high above Icecrown. It is there that you'll find my commanding officer, High Captain Bartlett. Tell him that I died a soldier of the Alliance.", sourceObjective = "Seek out High Captain Justin Bartlett aboard the Skybreaker flying above Icecrown.", completion = "<Captain Bartlett salutes.>\n\nHe was a damn fine soldier. Damn the Horde and damn the Scourge!", sourceObjectiveStatus = "unverified-source-field" }
quests[13226] = { id = 13226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you to answer the call, <brother/sister>. The Argent Crusade accepts all who would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", sourceObjective = "Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", completion = "My faithful knights have served me well. It seems that their recruitment efforts have yielded a hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[13227] = { id = 13227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you answer the call, <brother/sister>. The Argent Crusade accepts all that would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", sourceObjective = "Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", completion = "My faithful knights have served me well. It seems that their recruitment efforts have yielded a hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[13228] = { id = 13228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Front", description = "What battle?! Those troops were on a recon mission!\n\nAnd what's this talk of Alliance - you're sure he said Alliance?\n\nListen to me, {name}! I need to know what's going on and I need to know NOW!\n\nGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!", sourceObjective = "Korm Blackscar on Orgrim's Hammer wants you to go to The Broken Front and question a Dying Berserker to discover what happened there.", completion = "They saw the Alliance assaulting the gate and they attacked them from behind...\n\n<After a brief pause, Korm bursts into laughter.>\n\nTHAT is what it means to be HORDE!\n\nWere it not for them, the Alliance maggots would likely be holding that gate!\n\nTheir boldness has bought us precious time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13229] = { id = 13229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, {class}, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", sourceObjective = "Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer.", completion = "You have done well. We thought Father Kamaros lost, for certain. Your bravery will serve as an example to all those who oppose the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13230] = { id = 13230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Me!", description = "I hear them, <brother/sister>....\n\nThe moans of the wounded Alliance... they taunt me...\n\nFinish what we have begun here, {class}. Show no mercy... let none of them survive.\n\nFor... the Horde...", sourceObjective = "A Dying Berserker has asked that you slay 5 Dying Soldiers at the Broken Front. Report to Sky-Reaver Korm Blackscar on Orgrim's Hammer when it is done.", completion = "The time of tolerance for the Alliance has passed, {name}.\n\nThey have earned our hatred! They shall live in fear of the Horde until they no longer pollute our world!", sourceObjectiveStatus = "unverified-source-field" }
quests[13231] = { id = 13231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Front", description = "What?! Noooo!\n\nWe went to such great pains to keep this attack secret. How could the Horde have known? The resources... the men... all lost? Inconceivable!\n\nOur plans here in Icecrown hinged upon our taking that gate before the Horde could. We must recover quickly and prepare to mount another offensive.\n\nVisit the battlefield and search for any survivors. See if there's anything to be learned from this tragedy.\n\nAnd prepare yourself, {name}, for a war - on two fronts...", sourceObjective = "High Captain Justin Bartlett aboard the Skybreaker wants you to go to the Broken Front and question a Dying Soldier, then report back to him.", completion = "So... It was a rout - a total loss. This shall not be forgotten.\n\nMark my words, {class}. The Horde shall pay for this... there will be no mercy!", sourceObjectiveStatus = "unverified-source-field" }
quests[13232] = { id = 13232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish Me!", description = "They taunt us - even as they lie dying here...\n\nPlease, <brother/miss>... Don't allow their mocking to be the last sounds I hear...\n\nFinish me... deliver me from this torment... into... the Light.\n\nSeek out  my companions... offer them the same mercy.\n\nLeave nothing for the Scourge to raise!\n\nI beg you...", sourceObjective = "A Dying Soldier in the Broken Front wants you to kill 5 Dying Soldiers and report to High Captain Justin Bartlett on the Skybreaker.", completion = "That was a difficult thing you did, {class}. But it was the right thing.\n\nDon't allow the memory of your actions to haunt you. Harness that sorrow and pain you feel! Direct it at those who caused it.\n\nThe Horde must pay!", sourceObjectiveStatus = "unverified-source-field" }
quests[13233] = { id = 13233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy!", description = "It is as I told you. They were not merely idle words spoken in a fit of anger.\n\nTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.\n\nAll of them.\n\nJust imagine a world free of their stain, {name}. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.\n\nNow go, and make that vision a reality!", sourceObjective = "High Captain Justin Bartlett aboard the Skybreaker wants you to kill 15 Horde Players in Icecrown.", completion = "Well done, {name}!\n\nHunt them down and make them pay!", sourceObjectiveStatus = "unverified-source-field" }
quests[13234] = { id = 13234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Pay!", description = "The time has come!\n\nToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.\n\nNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!\n\nHere, at Icecrown, we break the Alliance!\n\nGo, {class}. Hunt them down. Break them. Take their will to live!", sourceObjective = "Sky-Reaver Korm Blackscar wants you to kill 15 Alliance Players in Icecrown.", completion = "You have done well, {class}.\n\nSoon, the Alliance shall run from you in fear and the Horde shall honor your name!", sourceObjectiveStatus = "unverified-source-field" }
quests[13235] = { id = 13235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flesh Giant Champion", description = "You've done well in destroying the Fleshwerks and slaughtering the Lich King's servants. Now, all that remains is to defeat the Fleshwerks' greatest accomplishment -- the flesh giant known as Morbidus.\n\nIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you're ready to begin the attack and he'll order his forces into battle.", sourceObjective = "Speak with Margrave Dhakar at the western end of the Fleshworks to engage Morbidus. After you have defeated Morbidus, report to Darkrider Arly at Blackwatch.", progress = "Have you finished off the Lich King's prized flesh giant?", completion = "With the Lich King's flesh giant champion defeated, he must know that the rest of his forces are vulnerable as well. With you by our side, we will teach the Lich King the meaning of fear once more.", sourceObjectiveStatus = "unverified-source-field" }
quests[13236] = { id = 13236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", sourceObjective = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", progress = "Did you see, {name}?", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13237] = { id = 13237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poke and Prod", description = "While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.\n\nIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.\n\nFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.\n\nI'll await your report, {class}.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to go the Broken Front and defeat 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts.", completion = "Really, {class}?\n\nNothing notable to report?\n\n\n\nI beg to differ...", sourceObjectiveStatus = "unverified-source-field" }
quests[13238] = { id = 13238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good For Something?", description = "Goblins! Hyper little busy-bodies...\n\nListen, {name}. Copperclaw, our resident engineer, is insisting that he's got something useful to show me.\n\nI'm in no mood to endure his squeaky nagging. The last time I acknowledged him, he chirped on for an hour straight. It was all I could do to keep from drop-kicking him into Sindragosa's Fall!\n\nYou go in my place and humor him. Let me know if indeed he's on to anything.", sourceObjective = "Sky-Reaver Korm Blackscar wants you to speak with Chief Engineer Copperclaw aboard Orgrim's Hammer.", completion = "Too busy? Phooey! This baby flies herself!\n\nNevermind that. You'll do...", sourceObjectiveStatus = "unverified-source-field" }
quests[13239] = { id = 13239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatility", description = "Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it's true, and I've recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I've developed a plan that just might work against them... now it'll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!\n\n...You still here, {race}?", sourceObjective = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", completion = "Wahooo! I saw them light up all the way from here! I'll just chalk that up as another success and begin bottling this stuff up for the invasion - of course it might need a little more testing as we go if you're at all interested....", sourceObjectiveStatus = "unverified-source-field" }
quests[13240] = { id = 13240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Centrifuge Constructs in your Future!", description = "It is into the Oculus floating above Coldarra that you must travel, {name}.\n\nI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.\n\nThus I have seen, thus you must do.", sourceObjective = "Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs.", completion = "<The archmage nods even before you say a word.>\n\nI know. You destroyed the constructs as I foresaw and were then able to go on to fight Varos Cloudstrider.\n\nExcellently done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13241] = { id = 13241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Ymirjar Berserkers in your Future!", description = "King Ymiron's champions stand between you and victory in the not-too-distant future.\n\nYou will travel to the fortress known as Utgarde Pinnacle nestled deep within the woods of the Howling Fjord. I cannot stress how important it is that you and your traveling companions deal with the Ymirjar berserkers therein.\n\nFailure to do so may very well doom you, {name}!", sourceObjective = "Archmage Timear in Dalaran wants you to slay 7 Ymirjar Berserkers.", progress = "<The archmage presses his fingers to his temples and concentrates.>\n\nThe berserkers have not yet been slain. Heed my warning, {name}. You must do this thing!", completion = "Outstanding work, {name}.\n\nWithout having done so, the surviving berserkers would surely have swarmed you during your fight with the king.", sourceObjectiveStatus = "unverified-source-field" }
quests[13242] = { id = 13242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Stirs", description = "Darkness stirs, {name}. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.\n\nThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.\n\nRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang.", sourceObjective = "Gather Saurfang's Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra.", progress = "<Saurfang's face contorts.>\n\nMy heart... my strength...", completion = "<Saurfang looks to the heavens.>\n\nLike Brox, my son died a hero. Do not mourn him, {name}. For an orc, there could be no better end! No greater honor! At this moment, my heart swells with pride.\n\nI thank you for returning our battle armor. It will be placed upon his pyre at the Ancestral Grounds of Nagrand.\n\nWe must turn our full attention to more pressing matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[13243] = { id = 13243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Infinite Agents in your Future!", description = "The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!\n\nYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.\n\nIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.\n\nOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!", sourceObjective = "Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents.", progress = "Time is always a precious resource, but even more so in this case, {name}. Please deal with the Infinite agents before it is too late!", completion = "We are saved for now. Thank you.\n\nUnfortunately due to the nature of their interference, the Infinite's will have almost unlimited opportunity to do so again.\n\nWhat I can discern is that in the future, you are at the heart of the struggle to stop them, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13244] = { id = 13244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Titanium Vanguards in your Future!", description = "The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!\n\nWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken's dread will upon countless unknowing victims.\n\nI have looked into the future, {name}. You are the one to see that this does not come to pass!", sourceObjective = "Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards.", progress = "Even I cannot discern why it is that we are standing here speaking when you have yet to eliminate the threat of the titanium vanguards.", completion = "We are all in your debt, {name}.\n\nIf I am certain of anything, it is that you have not failed us, nor will you in the future!", sourceObjectiveStatus = "unverified-source-field" }
quests[13245] = { id = 13245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Ingvar the Plunderer", description = "I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.\n\nI require his axe as proof that he has been dealt with. It's not that I don't trust you. It's simply prudent to be certain that the deed has been done.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Axe of the Plunderer.\n\nThis quest may only be completed on Heroic difficulty.", progress = "You have the axe? Ingvar is dead?", completion = "Very well. Just put the axe down over by the wall.\n\nI'm sure that Valgarde and Vengeance Landing will rest easier tonight knowing that you have dealt with that savage.", sourceObjectiveStatus = "unverified-source-field" }
quests[13246] = { id = 13246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Keristrasza", description = "Are you familiar with the story of Keristrasza?\n\nHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?\n\nWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.\n\n{name}, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.\n\nThough it saddens me, I must insist that you bring me her heart as proof.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with Keristrasza's Broken Heart.\n\nThis quest may only be completed on Heroic difficulty.", progress = "If we thought there was a way to redeem her, we wouldn't be asking you to put an end to her life.\n\nHowever, we know how powerful Malygos's command over magic has become. With his manipulations of Azeroth's ley-lines, he is without peer where matters arcane are concerned.", completion = "Regrettable, but extremely necessary.\n\nThe Kirin Tor could ill afford a prominent red dragon falling into the hands of our greatest enemy. Malygos's use of her against us in the Nexus War would have been devastating.\n\nI simply regret that we couldn't have saved her instead.", sourceObjectiveStatus = "unverified-source-field" }
quests[13247] = { id = 13247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Ley-Guardian Eregos", description = "The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, {name}?\n\nLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth's ley lines. If he can be slain it will be a great blow to the enemy.\n\nPlease bring me one of his ley line tuners so that we might study it.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with a Ley Line Tuner.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Has the ley-guardian been dealt with, {class}?\n\nI needn't remind you that Malygos is attempting to stop the use of all magic in the world, and that the blue dragonflight is slaying anyone that knows how to wield it who won't turn to their side?", completion = "Thank you, {name}. The examination of that tuner should provide us with further insights into how Malygos is manipulating the ley lines.\n\nIf we can find a weakness in his approach, we might be able to exploit it and turn the tide.", sourceObjectiveStatus = "unverified-source-field" }
quests[13248] = { id = 13248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: King Ymiron", description = "King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.\n\nBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!\n\nIt is up to you, {name}, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Ymiron must not be allowed to organize the vrykul nation. Should he return triumphantly to Icecrown, it is very likely that all will be lost.", completion = "<The archmage somberly nods as you hand him the rather large piece of jewelry.>\n\nWhat's done is done. Such a noble race these vrykul. It is unfortunate that the Lich King has sunk his deathly hooks into them.", sourceObjectiveStatus = "unverified-source-field" }
quests[13249] = { id = 13249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: The Prophet Tharon'ja", description = "Drak'Tharon Keep once stood as a proud bastion of the Drakkari nation. Now it is nothing more than a stepping stone for the Lich King in his fight to put an end to Zul'Drak and steal the powers of the troll gods.\n\nBut if we were to eliminate their leader, the Prophet Tharon'ja, perhaps we could stop the flow of Scourge troll reinforcements. At the very least this would give the Argent Crusade in Zul'Drak one less thing to worry about.\n\nReturn to me with his tiki so I will know the prophet is slain.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Prophet's Enchanted Tiki.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Have you faced the prophet? Do you have the tiki?", completion = "With any luck, now that it's leaderless, Drak'Tharon Keep will now prove less of a thorn in the side of those fighting against the Scourge in the region.\n\n<The archmage looks down at the tiki in your hand.>\n\nIt's just as well that the tiki has lost its mojo. I wouldn't have the first idea about how to use it, or even if it would be proper to do such a thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13250] = { id = 13250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Gal'darah", description = "The Drakkari prophets of Zul'Drak have done the unthinkable: they've slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal'darah.\n\nSequestered within the bowels of Gundrak, Gal'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!\n\nHurry, {name}, bring me what's left of Akali's mojo.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Do you have the mojo?\n\nIt is sickening to witness the demise of yet another great troll nation.\n\nI can only think that if it weren't for the interference of the Lich King, the trolls wouldn't have felt pressured to turn on their own gods and steal their power as a defense against the Scourge.", completion = "Thank you, {name}. I will see to it that the very essence of the god is kept safe until it can be handed over to the Zandalar tribe.\n\nPerhaps they'll be able to find a way to reincorporate Akali from it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13251] = { id = 13251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Mal'Ganis", description = "{name}, a friend within the bronze dragonflight has given me information that we must exploit.\n\nThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.\n\nHowever, it is known that Mal'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!\n\nThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We must capitalize on Mal'Ganis's mistake. It's not everyday that we get a chance like this.\n\nIf we can study that artifact, we may be able to gain a better understanding of the Nathrezim!", completion = "Amazing! I've never quite seen anything like it. I will see to it that it gets into the proper hands within the Violet Citadel.\n\nIf only you'd been allowed to change the course of history. Perhaps if Arthas had been kept from... no, down that path leads madness.\n\nSurely the Keepers of Time know best in these matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[13252] = { id = 13252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Sjonnir The Ironshaper", description = "Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.\n\nSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.\n\nRetrieve this disc for me, {name}, so that we may learn.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Curse of Flesh Disc.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Do you have the disc?", completion = "Is not Titan technology amazing? The information is contained within the disc itself!\n\nI only hope that we can figure out a way to get it out of the disc.", sourceObjectiveStatus = "unverified-source-field" }
quests[13253] = { id = 13253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Loken", description = "Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, {name}?\n\nHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!\n\nConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Celestial Ruby Ring.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We speak again, {name}. Does this mean that we are safe from Loken's madness, or are we doomed?", completion = "<Archmage Lan'dalock breathes a sigh of relief.>\n\nTo be honest, I feared the worst had befallen you. It's difficult to stand idly by while others, such as yourself, deal with the matters of life and death which confront our world seemingly on a daily basis.\n\nNow what are we going to do with that gigantic ring?", sourceObjectiveStatus = "unverified-source-field" }
quests[13254] = { id = 13254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Anub'arak", description = "The Scourged nerubians are a plague upon our forces.\n\nWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.\n\nIt's in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub'arak.\n\nPlease bring me his crown... not that he wears it any longer.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Idle Crown of Anub'arak.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I'm glad that it's you going down into Azjol-Nerub and not myself.\n\nI do not like being under the world.", completion = "What horrors you must have faced while traversing the Upper City.\n\n<Lan'dalock glances down at the tarnished crown clutched in your fist.>\n\nPerhaps we should put that aside for their new king whenever the nerubians decide to coronate one?", sourceObjectiveStatus = "unverified-source-field" }
quests[13255] = { id = 13255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Herald Volazj", description = "The nerubians of Ahn'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.\n\nRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.\n\nThe leader of the Old Gods' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.\n\nJust please, try to keep your sanity.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Faceless One's Withered Brain.\n\nThis quest may only be completed on Heroic difficulty.", progress = "{name}? Are you still sane?", completion = "<The archmage eyes the brain warily.>\n\nNow that I think of it, I'm not quite sure that it's safe to be so near to that thing. You say that it's still alive?\n\n<He shakes his head.>\n\nWe have a place for such things in the citadel. I'll see to it that one of my apprentices takes it there straight away.", sourceObjectiveStatus = "unverified-source-field" }
quests[13256] = { id = 13256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Cyanigosa", description = "We're being invaded! The blue dragonflight has teleported into the Violet Hold and they're planning on breaking out from there into the rest of Dalaran!\n\nThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn't surprise me if they're purposefully letting some of them free.\n\n{name}, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Head of Cyanigosa.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Come to think of it, why would you ever teleport into a prison to break out of it? It's only the most secure place in the city.\n\nI think the blues must have truly gone insane!", completion = "The danger is over and the rest of the prisoners that had broken free are being imprisoned once more.\n\nDalaran owes you a debt of gratitude, {name}!\n\nNow I need to go speak with someone about why it was so easy to bypass the city's anti-teleportation protections within the prison?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13257] = { id = 13257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herald of War", description = "The Warchief needs you, champion. Orgrimmar is in a state of martial law. All merchants and services have been shut down as the Warchief prepares for an unavoidable conflict.\n\nI cannot tell you much more - not now. Not in this place.\n\nThe Warchief commands that our strongest champions report to his throne room. Go now, {name}! Take the portal back to Orgrimmar and seek out Thrall.", sourceObjective = "Report to Thrall at Grommash Hold in Orgrimmar.", completion = "The demon lord, Varimathras, and the Forsaken's chief apothecary, Putress, are responsible for this betrayal.\n\n<Thrall nods.>\n\nYes, the same Putress responsible for discovering the cure for the recent Scourge plague outbreak.\n\nThose that would not side with their regime have been executed or banished. Sylvanas was nearly killed in the coup.\n\nThe Horde has lost the Undercity. Orgrimmar will take on the Forsaken refugees until there is a resolution to this crisis. For now we are under martial law.", sourceObjectiveStatus = "unverified-source-field" }
quests[13258] = { id = 13258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opportunity", description = "We recently came upon schematics that indicate a weakness in Icecrown Citadel.  An opening in its defenses, both figuratively and literally.\n\nThe captured diagrams show an orifice leading several hundred feet into the ground.  We're unsure of its purpose, but our scouting has revealed it to be of high importance to the Scourge.\n\nSpeak to Sergeant Kregga below Icecrown Citadel, she's leading the attack on the site.", sourceObjective = "Speak to Sergeant Kregga below Icecrown Citadel.", completion = "Just in time, {name}.  Koltira spoke highly of you.  Perhaps you'll be able to push the scales in our favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[13259] = { id = 13259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing Superiority", description = "We've one shot at dealing some damage to this place -- let's make sure we get it right.\n\nWe've acquired potent, Scourge-made, saronite bombs.  But we must secure this area before we can set them off.\n\nWe're going to need to get the Scourge defenses under control quickly, before reinforcements arrive.\n\nHelp my men out and come back when you're ready for some fireworks.", sourceObjective = "Sergeant Kregga at Icecrown Citadel wants you to slay 10 Hulking Horrors.", progress = "For honor, {name}.", completion = "You made quick work of the Scourge, {name}.  Let's finish what we came to do here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13260] = { id = 13260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", sourceObjective = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", completion = "<Koltira looks you up and down.>\n\nI hope for your sake that you're up to this, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13261] = { id = 13261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatility", description = "Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn't quite sure what kind of explosion to expect - let's just say I'm glad to see that you didn't get your eyebrows singed off. So now I just need to show ol' Korm how ya thaw out one 'a them wyrms. He'll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I'll go get Korm...\n\nWell? Move out!", sourceObjective = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", completion = "No good!\n\nKorm kept telling me he was too busy and when I finally got him to come topside and have a look, you had already used the last of the oil. Now he's ticked at me and won't even allow me in his presence again until tomorrow...\n\nCome back then and we'll try again!", sourceObjectiveStatus = "unverified-source-field" }
quests[13262] = { id = 13262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blow it Up!", description = "This is probably as under-control as this situation is going to get.  Let's do this, {name}.\n\nI need someone to light the fuse on those bombs and it looks like you're the one to do it.", sourceObjective = "Go to the nearby Saronite Bomb Stack to light the fuse.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure.", sourceObjectiveStatus = "unverified-source-field" }
quests[13263] = { id = 13263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", sourceObjective = "Look for clues wherever the fall takes you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water.", sourceObjectiveStatus = "unverified-source-field" }
quests[13264] = { id = 13264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", sourceObjective = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "You see, {class}?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[13265] = { id = 13265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Turn that extra cloth you find into something that looks marvelous!" }
quests[13266] = { id = 13266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Life Without Regret", description = "On the day of my death I wish to be able to say that I lived a life without regret. Those who mourn my passing will know that I was a Warchief who made decisions that best served his people.\n\nBut this betrayal by Varimathras and Putress... All that we have worked for is for nothing.\n\n<Thrall's chest heaves with a heavy sigh.>\n\nJustice must be served.\n\nPortals to Undercity will be active momentarily. Vol'jin will be waiting for you. I will meet you there soon. Together we will make it right, {name}.", sourceObjective = "Take the portal to Undercity located in Grommash Hold and report to Vol'jin.", completion = "Let me get you up to speed, {name}.\n\nUndercity is a war-zone. Putress' apothecaries and Varimathras' demons have seized control. They've taken a defensive position inside and are using that damned blight against our troops.", sourceObjectiveStatus = "unverified-source-field" }
quests[13267] = { id = 13267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Undercity", description = "The entirety of the Undercity is controlled by Varimathras. Our soldiers stand ready, waiting for the Warchief to give the attack orders.\n\nHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.\n\nCheck in with the Warchief when you are ready to begin.", sourceObjective = "Assist Thrall and Sylvanas in retaking the Undercity for the Horde.\n\nReport to Thrall should you succeed.", completion = "Tomorrow brings with it uncertainty. Gone are the days of Alliance and Horde battling alongside each other in pursuit of a common enemy. A new battle dawns, {name} - a battle in which there can be no victor.\n\nBut we must continue our march towards Icecrown. We have no choice in that matter. Our salvation lies with heroes like you, {name}. The future of the Horde - of the world - depends on you.\n\nLet us return to Orgrimmar. You must return to Northrend at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[13268] = { id = 13268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Come back when you have the skill and I can provide all of your tailoring training." }
quests[13269] = { id = 13269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", completion = "May you slay many humanoids and take their cloth." }
quests[13270] = { id = 13270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", completion = "I be appreciatin' your business." }
quests[13271] = { id = 13271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", sourceObjective = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13272] = { id = 13272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "I think you will find this skill helps you a great deal on your path to tailoring greatness!" }
quests[13273] = { id = 13273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going After the Core", description = "With Norgannon's Shell in hand, only half of the archive key remains to be found. Luckily, I've had the Explorers' League hard at work chasing down leads about the whereabouts of Norgannon's Core.\n\nFar to the southeast of the Inventor's Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they've made and we should be able to track down the other key half.", sourceObjective = "Find Prospector Khrona's Notes and Prospector Soren's Maps at Brann's Base-Camp.", progress = "Have you recovered those notes?", completion = "Ruined? What d'you mean, the camp's been ruined?\n\n<Brann clenches his fists in anger.>\n\nThose iron dwarves will pay for this! There's little we can do now, and we have to focus on finishing the key. But once I get into the halls of Ulduar, the irons and their masters will answer for what they've done!", sourceObjectiveStatus = "unverified-source-field" }
quests[13274] = { id = 13274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Core's Keeper", description = "Prospector Soren's notes say that Norgannon's Core is in the keeping of a sentinel named Athan, one of Mimir's creations.\n\nSoren says the vault where Athan resides is called \"Loken's Bargain\" these days.\n\nLoken, eh? The earthen have mentioned him.\n\nThe vault is said to be southwest of the ruined Explorers' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.\n\nFind this Athan and get the core from him, but I wouldn't be surprised if you were in for a fight.", sourceObjective = "Obtain Norgannon's Core.", progress = "Was Prospector Soren right? Did you finally find Norgannon's Core?", completion = "This is really it! The key is almost within our grasp. All we need now is a way to combine the shell and the core into a single key. Let's see what Prospector Soren had to say about this...", sourceObjectiveStatus = "unverified-source-field" }
quests[13275] = { id = 13275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", sourceObjective = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13276] = { id = 13276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make our assault on the gate.", sourceObjective = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the gate will belong to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13277] = { id = 13277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", sourceObjective = "Koltira Deathweaver on Orgrim's Hammer wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", progress = "Any success against the giants, {race}?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them....", sourceObjectiveStatus = "unverified-source-field" }
quests[13278] = { id = 13278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to kill Coprous the Defiled at Mord'rethar.", completion = "Well done, {class}.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence.", sourceObjectiveStatus = "unverified-source-field" }
quests[13279] = { id = 13279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Chemistry", description = "<Koltira takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", completion = "You have done well, {class}.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13280] = { id = 13280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Mountain", description = "You've just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, {name}!\n\nThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I'm afraid he almost has it completed. We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!", sourceObjective = "Frazzle Geargrinder in Ymirheim wants you to use her Geargrinder's Jumpbot to plant the Alliance Battle Standard in the skulls at the top of the mountain.", progress = "Hold on a second... you haven't planted our battle standard yet!\n\nWhat's the hold up?", completion = "YOU DID IT! YOU DID IT!\n\n<Frazzle jumps and gives you a big hug.>\n\nOh, you're just my favorite hero ever!\n\nYou think you could come back again tomorrow?", sourceObjectiveStatus = "unverified-source-field" }
quests[13281] = { id = 13281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you use Pustulant Spinal Fluid on a blight cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour commander will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[13282] = { id = 13282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", sourceObjective = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "{name}!  We thought you were dead!\n\nWe lost a few men in that explosion... but we sure put a hurt on the Scourge.  They're scrambling their forces back to the citadel and leaving big gaps in their defenses.  It's time to push forward.", sourceObjectiveStatus = "unverified-source-field" }
quests[13283] = { id = 13283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Mountain", description = "Yo, {name}, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!\n\nThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot's better than mine. Hah! We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!", sourceObjective = "Blast Thunderbomb in Ymirheim wants you to use his Thunderbomb's Jumpbot to plant the Horde Battle Standard in the skulls at the top of the mountain.", progress = "Hold on a second... you haven't planted our battle standard yet!\n\nWhat gives?", completion = "I knew you were the right {race} for the job!\n\n\n\nI gotta admit that right now you're my favorite {class} of all time!\n\nWhat do you say to a repeat performance again tomorrow? I can make it worth your while!", sourceObjectiveStatus = "unverified-source-field" }
quests[13284] = { id = 13284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", sourceObjective = "Escort the Skybreaker troops to the gates of Ymirheim. Return to Ground Commander Koup at the edge of the glacier east of Ymirheim for compensation after the task is complete.", progress = "Did you get some of my men up safely?", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[13285] = { id = 13285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Keystone", description = "Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that's where one would go to join the two parts of the key.\n\nAccording to the prospector's notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom'arsh Crash Site.\n\nI'll meet you at the temple and we'll combine the parts together.", sourceObjective = "Brann Bronzebeard wants you to meet him at the Temple of Invention and help him combine Norgannon's Shell and Norgannon's Core. Once you have helped Brann, report back to Boktar Bloodfury at the Grom'arsh Crash-Site.", progress = "Do you have the completed keystone?", completion = "<Boktar nods in approval as you tell him how you helped Brann recover the pieces of the keystone and combine them.>\n\nBrann may prove to be just the ally we need to discover what is truly happening in Ulduar. You've done well in aiding him. We need all the help we can get against this Loken and his iron dwarf minions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13286] = { id = 13286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...All the Help We Can Get.", description = "Desperate times, {class}...\n\nAs uncomfortable as it makes me, I'm prepared to accept assistance from anyone - including our resident death knight.\n\nGo to Thassarian and see if he can help us develop tactics against the Scourge that will ensure victory once we are able to mount another offensive.\n\nWe have come so far... we must not fail here!", sourceObjective = "High Captain Justin Bartlett aboard the Skybreaker wants you to speak to Thassarian.", completion = "It was wise of Captain Bartlett to send you.\n\nWhile he frets over your conflict with the Horde, someone must remain exclusively focused on the real mission here - the march on Icecrown Citadel.\n\nWho better to direct your efforts than a former servant of the Lich King?", sourceObjectiveStatus = "unverified-source-field" }
quests[13287] = { id = 13287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poke and Prod", description = "As someone of your experience must surely know, there's no better way to familiarize one's self with their enemy than by confronting them in combat.\n\nWhile you no doubt lust for the glory of taking Icecrown Citadel, that cannot happen without taking each of the Lich King's gates first. For now, you must focus your efforts on the first of these...\n\nReturn to the Broken Front. Engage the enemy in battle. Search for a weakness we might exploit and return to me with a detailed report.", sourceObjective = "Thassarian on the Alliance gunship, Skybreaker, wants you to kill 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts at the Broken Front.", progress = "You've returned, {class}...\n\nAnything to report?", completion = "Really, {class}?\n\nNothing notable to report?\n\n\n\nI beg to differ...", sourceObjectiveStatus = "unverified-source-field" }
quests[13288] = { id = 13288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", sourceObjective = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", progress = "Well, {race}?\n\nDid your abomination friends prove effective?", completion = "You see, {class}?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[13289] = { id = 13289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make another assault on the gate.", sourceObjective = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the death gate will belong to the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13290] = { id = 13290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Attention, Please", description = "Chief Engineer Boltwrench has proven invaluable in his service aboard the Stormbreaker. Were it not for his ingenuity, we'd be sprinkled across half of the glacier several times over by now.\n\nThe thing is, he feels he must share his every miniscule invention or discovery - most of which I don't even understand.\n\nMy focus must be squarely on our enemies right now. I cannot afford any distractions.\n\nPlease visit him in my stead, {name}. And if you can, assist him. You'll find him belowdecks.", sourceObjective = "High Captain Bartlett wants you to speak with Chief Engineer Boltwrench in the Skybreaker.", completion = "Cappy sent you in his place, did he?\n\nVery well, {class}. Roll up those sleeves... time to get to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[13291] = { id = 13291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Technology", description = "I get it, I get it. Cappy's too busy to see this for himself. His loss!\n\nSee, I've managed to 'acquire' a certain shipment of solution from the enemy. And as much as I hate tinkerin' with inferior goblin technology, I'm inclined to make an exception here.\n\nTake this sample. I'll need you to run a few field tests, just to prove its usefulness, while I try to do a little reverse engineering to duplicate the creation process.\n\nGo to the front and gather the materials to make a decoy, then use the oil.", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", completion = "Good news!\n\nI've managed to reproduce the solution - hardly an accomplishment, of course.\n\nDoubt I'll live to see the day those neanderthal goblins cook up somethin' a gnome can't recreate in his sleep!", sourceObjectiveStatus = "unverified-source-field" }
quests[13292] = { id = 13292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Solution Solution", description = "Oh, yes, yes. Back again, are we? Never enough practice, I suppose.\n\nHere we are, the solution to that pesky frostwyrm problem.\n\nMake them scarce, {race}. The more you take out now, the less we face when we are again ready to attempt our march on the citadel.\n\nBest of luck, now. And do bring back whatever you don't use.", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", progress = "Yes, friend?", completion = "Good show! Good show indeed. You're turning into a regular wyrmslayer!\n\nCome back when you're ready to thin their numbers even further.", sourceObjectiveStatus = "unverified-source-field" }
quests[13293] = { id = 13293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Ymirheim!", description = "You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It's his jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those cowards in the pants!", sourceObjective = "Speak with Blast Thunderbomb in Ymirheim.", completion = "Oh man, am I glad to see you! Did the chief send you down from the Hammer?", sourceObjectiveStatus = "unverified-source-field" }
quests[13294] = { id = 13294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", sourceObjective = "Thassarian on the Skybreaker wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", progress = "Any success against the giants, {race}?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them....", sourceObjectiveStatus = "unverified-source-field" }
quests[13295] = { id = 13295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Chemistry", description = "<Thassarian takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", sourceObjective = "Thassarian aboard the Skybreaker wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", completion = "You have done well, {class}.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13296] = { id = 13296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Ymirheim!", description = "I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It's her jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those idiots in the pants!", sourceObjective = "Speak with Frazzle Geargrinder in Ymirheim.", completion = "Did the chief send you down from the Skybreaker? Isn't that thing sweet?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13297] = { id = 13297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", sourceObjective = "Thassarian aboard the Skybreaker wants you use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour captain will be highly pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[13298] = { id = 13298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", sourceObjective = "Thassarian aboard the Skybreaker wants you to kill Coprous the Defiled at Mord'rethar.", completion = "Well done, {class}.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence.", sourceObjectiveStatus = "unverified-source-field" }
quests[13299] = { id = 13299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDWisp Cloak" }
quests[13300] = { id = 13300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, {name}?", sourceObjective = "Absalan the Pious aboard the Skybreaker wants you to rescue 10 Saronite Mine Slaves.", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13301] = { id = 13301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", sourceObjective = "Escort the Kor'kron troops to the gates of Ymirheim. Return to Ground Commander Xutjja at the edge of the glacier north of Ymirheim for compensation after the task is complete.", progress = "Did you get some of my men up safely?", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[13302] = { id = 13302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, {name}?", sourceObjective = "Brother Keltan aboard Orgrim's Hammer wants you to rescue 10 Saronite Mine Slaves.", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13304] = { id = 13304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Repairs", description = "The Scourge is still reeling from our attack, {name}.  Now is the time to capitalize on our momentum.\n\nThe strategically important valley below us is wide open.  We've located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.\n\nIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy's ground units.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to collect 5 Demolisher Parts from the Scavenging Geists in the Valley of Lost Hope and take them to the Wrecked Demolisher.", progress = "The demolisher has suffered much damage.", completion = "The Demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[13305] = { id = 13305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", sourceObjective = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, {name}.  Let me show you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13306] = { id = 13306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Koltira nods curtly.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[13307] = { id = 13307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and thin the resistance before the main body can advance.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[13308] = { id = 13308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Tricks", description = "<The creature speaks directly into your mind, its thoughts painful and strange.>\n\n{race}-thing, I am in need of your assistance. Like your enslaved friends, I am a victim of the Lich King's ymirjar and their avarice. When I rose from below to investigate the noises coming from this cavern they captured and chained me.\n\nWill you please help me? The foreman of these mines holds the key to my chains. Kill him!\n\n<You can feel a pushing against your mind as if the creature is trying to coerce you.>", sourceObjective = "Darkspeaker R'khem in the Saronite Mines wants you to recover the Foreman's Key to his chains.", progress = "You will be richly rewarded for your service to me.\n\n<The darkspeaker projects soothing feelings into your mind.>\n\nYou will not regret unfettering me.", completion = "<Another wave of euphoria, mixed with some pain, crashes through your mind as you approach the creature.>\n\nGood... good! So that you know I am being fair, I will first give you your reward as promised.\n\nAnd then you will willingly hand me the key.", sourceObjectiveStatus = "unverified-source-field" }
quests[13309] = { id = 13309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Air", description = "I've got some boys suited and ready for their drops inside of Ymirheim. I could use you to see them there safely.\n\nInside the walls, the vrykul have set up some kind of automated spear guns that have been tearing up our transports. We had our engineers install a Suppression Turret to shut down those spear guns - just fire a round near any gun and the smoke should block its sight and clog its gears.\n\nHop on the turret and see to it that all my boys make it to their drops in one piece.", sourceObjective = "Ground Commander Koup at the edge of the glacier east of Ymirheim has ordered you to use the Skybreaker Suppression Turret to keep the Skybreaker Troop Transport alive long enough to make all of its drops.", progress = "Did you get my boys inside?", completion = "Excellent work, soldier. We could use more able bodies like you around here - stop by another day if the operation hasn't wrapped up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13310] = { id = 13310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Air", description = "Alright scrub, I've got something to keep you from being a complete waste.\n\nA unit of highly trained infiltrators is ready to be dropped inside of Ymirheim. The vrykul inside have automated spear guns that have been ripping our transports to shreds, so we had the engineers on Orgrim's Hammer whip us up a suppression turret.\n\nYou're the gunner. Launch rounds at their spear guns to obscure their vision and clog their gears. See to it that my men all make their drops and the transport stays in one piece.", sourceObjective = "Ground Commander Xutjja at the edge of the glacier north of Ymirheim has ordered you to use the Kor'kron Suppression Turret to keep the Kor'kron Troop Transport alive long enough to make all of its drops.", progress = "Get the job done?", completion = "Only partly useless then. Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[13311] = { id = 13311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Deck", description = "Now that you have gathered all of the Demon cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", sourceObjective = "Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Demons!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13312] = { id = 13312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", sourceObjective = "Defeat Grimkor the Wicked and return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13313] = { id = 13313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Eyes in the Sky", description = "The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur'thar.\n\nThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.", sourceObjective = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", completion = "Good. Fewer Alliance pests to stand in our way. We'll show them what true warriors look like.", sourceObjectiveStatus = "unverified-source-field" }
quests[13314] = { id = 13314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Message", description = "The Horde is up to something and I don't like it. After the stunt they pulled on the Broken Front, they're capable of anything, and it's up to us to stop it.\n\nThere's been a flurry of activity in the skies over the Icecrown Glacier, to the west of Aldur'thar and the Ironwall Rampart. Horde scouts and messengers streak in and out on dragonhawks, carrying reports and orders. Take this dart gun and use it to kill the Orgrim's Hammer Scouts. It'll probably work best if you're flying, too.", sourceObjective = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "It's good to have someone competent running missions, {name}. If only we had an army of paladins like you, we could show the Horde what we're made of. These captured reports will help us to maintain the upper hand in this fight. We may be down, but we're far from out.", sourceObjectiveStatus = "unverified-source-field" }
quests[13315] = { id = 13315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from those Horde you insist on contending with...\n\nAt any rate, our next focus will be the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", progress = "Have you scouted the gate of desolation, {class}?", completion = "Well and good, {class}.\n\nNow that you've seen firsthand what we're up against, it's time to get to work...", sourceObjectiveStatus = "unverified-source-field" }
quests[13316] = { id = 13316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13318] = { id = 13318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13319] = { id = 13319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", sourceObjective = "Thassarian aboard the Skybreaker wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", completion = "Well done, {race}. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time...", sourceObjectiveStatus = "unverified-source-field" }
quests[13320] = { id = 13320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Boltwrench.", sourceObjective = "Thassarian aboard the Skybreaker wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Boltwrench.", progress = "Whatdya got there, {race}?", completion = "<Boltwrench pours the contents of the flask into his tetrahydroparticle analyzer.>\n\nWhat we have here is a simple failure to conglomerate...", sourceObjectiveStatus = "unverified-source-field" }
quests[13321] = { id = 13321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13322] = { id = 13322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to drink the Diluted Cult Tonic, kill any Cultists at Aldur'thar and take their Tainted Essences. You are then to combine 10 of the essences into a Writhing Mass and throw it into any of their cauldrons.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13323] = { id = 13323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13324] = { id = 13324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Prisms Deck", description = "Now that you have gathered all of the Prism cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Prisms Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Prisms!   Congratulations!", completion = "So you have put together a deck of Prisms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13325] = { id = 13325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Chaos Deck", description = "Now that you have gathered all of the Chaos cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Chaos Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Chaos!   Congratulations!", completion = "So you have put together a deck of Chaos.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13326] = { id = 13326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Nobles Deck", description = "Now that you have gathered all of the Nobles cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Nobles Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Nobles!   Congratulations!", completion = "So you have put together a deck of Nobles.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13327] = { id = 13327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Undeath Deck", description = "Now that you have gathered all of the Undeath cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Undeath Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Undeath!   Congratulations!", completion = "So you have put together a deck of Undeath.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13328] = { id = 13328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", sourceObjective = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Koltira Deathweaver aboard Orgrim's Hammer.", progress = "Have you shattered the Lich King's new weapons?", completion = "<Koltira takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13329] = { id = 13329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to use the Volatile Acid to dissolve the remains of 6 Skeletal Reavers.", completion = "<Koltira listens to your report.>\n\nGood. I'll have the engineers mix up as much of that acid as they can before we prepare to assault Corp'rethar with the main force.", sourceObjectiveStatus = "unverified-source-field" }
quests[13330] = { id = 13330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", sourceObjective = "Warbringer Davos Rioht on Orgrim's Hammer has sent you to kill 20 vrykul in Ymirheim.", completion = "Not so strong after all, it seems. The Lich King will get what's coming to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[13331] = { id = 13331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Alliance Blind", description = "The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.\n\nI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.", sourceObjective = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", progress = "Have you eliminated the Alliance's reconnaissance operations in the western part of the glacier?", completion = "Well done, once again. Horde superiority is assured, at least until those Alliance pukes decide to challenge us again.", sourceObjectiveStatus = "unverified-source-field" }
quests[13332] = { id = 13332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Thassarian nods.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[13333] = { id = 13333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture More Dispatches", description = "Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.\n\nWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.\n\nThe Horde's wasted efforts will be our gain.", sourceObjective = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "<The high captain accepts the dispatches.>\n\nThis is just what we need. Not even the Horde is so stupid as to charge in blindly against the Scourge. With their reports in hand, we'll be well prepared.", sourceObjectiveStatus = "unverified-source-field" }
